insert into milestones (key, title, description, milestone_type, requirement_metric, requirement_count, icon_key, is_active) values
  ('first-step', 'First Step', 'Your first quest, done. That''s how every pilgrimage starts.', 'first_step', 'quest_completions', 1, 'path', true),
  ('first-prayer', 'First Prayer', 'You wrote your first prayer. Honest words count.', 'first_step', 'prayers_created', 1, 'candle', true),
  ('first-reflection', 'First Reflection', 'You noticed something worth writing down. That''s the whole practice.', 'first_step', 'reflections_created', 1, 'leaf', true),
  ('first-answered-prayer', 'First Answer', 'You marked a prayer answered — worth remembering.', 'first_step', 'prayers_answered', 1, 'bird', true),
  ('first-chapter', 'First Chapter', 'You read your first chapter. No schedule, no rush.', 'first_step', 'chapters_read', 1, 'book', true),
  ('first-bookmark', 'First Verse', 'You saved your first verse — words worth coming back to.', 'first_step', 'verses_bookmarked', 1, 'bookmark', true),
  ('seven-mornings', 'Seven Days', 'You showed up seven days. A rhythm is forming.', 'rhythm', 'journey_days', 7, 'sun', true),
  ('month-of-mornings', 'Thirty Days', 'Thirty days, all told. That''s a practice now.', 'rhythm', 'journey_days', 30, 'sun', true),
  ('steady-steps', 'Ten Quests', 'Ten quests done, one at a time.', 'rhythm', 'quest_completions', 10, 'path', true),
  ('into-the-story', 'Into the Story', 'Ten chapters read. The story is opening up.', 'scripture', 'chapters_read', 10, 'book', true),
  ('deep-roots', 'Deep Roots', 'Twenty reflections. That kind of attention goes deep.', 'depth', 'reflections_created', 20, 'tree', true),
  ('practice-of-prayer', 'Ten Prayers', 'Ten prayers written — an honest conversation with God, in practice.', 'prayer', 'prayers_created', 10, 'candle', true),
  ('words-for-the-road', 'Ten Verses', 'Ten verses saved, each one worth returning to.', 'scripture', 'verses_bookmarked', 10, 'bookmark', true),
  ('gathered-graces', 'Five Answers', 'Five prayers answered — and you noticed every one.', 'prayer', 'prayers_answered', 5, 'star', true),
  ('kept-vigil', 'Steady in Prayer', 'Five quests centered on prayer. You keep showing up.', 'prayer', 'quests_prayer', 5, 'lantern', true),
  ('by-lamplight', 'Word by Word', 'Seven Scripture quests. The Word is becoming familiar ground.', 'scripture', 'quests_scripture', 7, 'lantern', true),
  ('encourager', 'Encourager', 'Five kindness quests — people leave a little lighter than you found them.', 'kindness', 'quests_kindness', 5, 'flower', true),
  ('quiet-strength', 'Quiet Strength', 'You served others three times. No audience needed.', 'kindness', 'quests_service', 3, 'tree', true),
  ('counted-gifts', 'Counted Gifts', 'Seven times you stopped to give thanks — for things easy to miss.', 'rhythm', 'quests_gratitude', 7, 'star', true),
  ('still-waters', 'Still Waters', 'Three times you sat still and let that be enough.', 'depth', 'quests_silence', 3, 'leaf', true),
  ('around-the-table', 'Around the Table', 'Faith practiced at home, three times over.', 'kindness', 'quests_family', 3, 'flower', true),
  ('fellow-travelers', 'Fellow Travelers', 'Three quests with your community. The road is better with company.', 'kindness', 'quests_community', 3, 'chapel', true),
  ('three-mornings', 'A Rhythm Begins', 'You returned on three different days. A practice starts by coming back.', 'rhythm', 'journey_days', 3, 'sun', true),
  ('two-weeks-returning', 'Two Weeks Returning', 'Fourteen days along the road, made from ordinary moments of attention.', 'rhythm', 'journey_days', 14, 'path', true),
  ('season-of-returning', 'A Season of Returning', 'You have returned on ninety days. The rhythm has had time to take root.', 'rhythm', 'journey_days', 90, 'tree', true),
  ('many-small-steps', 'Many Small Steps', 'Twenty-five quests completed. Small acts have become a well-worn path.', 'rhythm', 'quest_completions', 25, 'path', true),
  ('fifty-quests', 'The Longer Road', 'Fifty quests completed, each one lived beyond the screen.', 'rhythm', 'quest_completions', 50, 'mountain', true),
  ('deeper-into-the-story', 'Deeper into the Story', 'Twenty-five chapters read. Familiar words are becoming a larger story.', 'scripture', 'chapters_read', 25, 'open-book', true),
  ('prayer-woven-in', 'Prayer Woven In', 'Twenty-five prayers written across whatever the days held.', 'prayer', 'prayers_created', 25, 'candle', true),
  ('pages-of-attention', 'Pages of Attention', 'Fifty reflections. You kept making room to notice what was happening within and around you.', 'depth', 'reflections_created', 50, 'fountain', true),
  ('small-treasury', 'A Small Treasury', 'Twenty-five verses saved — a collection of words worth carrying.', 'scripture', 'verses_bookmarked', 25, 'bookmark', true),
  ('graces-remembered', 'Graces Remembered', 'Ten prayers marked answered. You paused long enough to remember each one.', 'prayer', 'prayers_answered', 10, 'bird', true),
  ('mercy-practiced', 'Mercy Practiced', 'Three forgiveness quests. Mercy took shape in choices you could actually make.', 'depth', 'quests_forgiveness', 3, 'links', true),
  ('open-hands', 'Open Hands', 'Three generosity quests. You made room to give without needing to be noticed.', 'kindness', 'quests_generosity', 3, 'wheat', true),
  ('steady-practice', 'Steady Practice', 'Five discipline quests. A faithful practice is being built one choice at a time.', 'rhythm', 'quests_discipline', 5, 'lantern', true),
  ('ordinary-worship', 'Worship in Ordinary Days', 'Five worship quests. Attention and praise found a home in everyday life.', 'prayer', 'quests_worship', 5, 'chapel', true),
  ('attentive-heart', 'An Attentive Heart', 'Five reflection quests. You practiced staying with what was worth noticing.', 'depth', 'quests_reflection', 5, 'fountain', true),
  ('patient-steps', 'Patient Steps', 'Five patience quests. You kept choosing the slower, steadier way.', 'depth', 'quests_patience', 5, 'path', true)
insert into prayer_prompts (key, text, category, is_active) values
  ('p01', 'Father, thank you for this morning. Walk with me through whatever it holds.', 'morning', true),
  ('p02', 'Lord, before the day gets loud, let me begin it with you.', 'morning', true),
  ('p03', 'God, I don''t know what today will bring. Help me take it one step at a time, with you.', 'morning', true),
  ('p04', 'Father, the day is done. Help me set it down and rest in you.', 'evening', true),
  ('p05', 'Lord, thank you for carrying me through today, even the parts I barely noticed.', 'evening', true),
  ('p06', 'Jesus, quiet my mind tonight. Let me end this day grateful instead of restless.', 'evening', true),
  ('p07', 'God, open my eyes to the ordinary gifts I walk past every day.', 'gratitude', true),
  ('p08', 'Father, thank you for the small mercies of today, the ones I noticed and the ones I missed.', 'gratitude', true),
  ('p09', 'Lord, teach me a gratitude that lasts longer than the moment.', 'gratitude', true),
  ('p10', 'God, this is hard and I don''t understand it. Stay close to me anyway.', 'difficulty', true),
  ('p11', 'Lord, I''m tired. Give me enough strength for today, and help me trust you with tomorrow.', 'difficulty', true),
  ('p12', 'Father, I can''t see the way through this. Help me take the next step.', 'difficulty', true),
  ('p13', 'Lord, be near the person I''m worried about tonight. Hold them when I can''t.', 'intercession', true),
  ('p14', 'Father, I bring you my friend who is hurting. Give them what I don''t know how to give.', 'intercession', true),
  ('p15', 'God, comfort the people who feel forgotten today, and help me notice the ones close to me.', 'intercession', true),
  ('p16', 'Lord, slow me down. Teach me to sit quietly with you.', 'stillness', true),
  ('p17', 'Father, quiet the noise in me. I want to listen more than I speak.', 'stillness', true),
  ('p18', 'Jesus, I am always hurrying somewhere. Help me stop long enough to notice you here.', 'stillness', true),
  ('p19', 'Father, I''m holding on to an old hurt. Help me loosen my grip and let mercy in.', 'forgiveness', true),
  ('p20', 'God, forgive me for the ways I hurt people today, even the ways I didn''t see.', 'forgiveness', true),
  ('p21', 'Jesus, forgiving this person feels beyond me. Begin it in me anyway.', 'forgiveness', true),
  ('p22', 'Lord, give me courage for the conversation I''ve been avoiding, and the wisdom to know whether and when the time is right.', 'courage', true),
  ('p23', 'God, help me do the right thing today, even when it''s the quiet, unnoticed thing.', 'courage', true),
  ('p24', 'Father, I''m afraid. Remind me that you go with me.', 'courage', true),
  ('p25', 'Lord, give me patience with the people closest to me, the ones who see me at my worst.', 'family', true),
  ('p26', 'Father, bless my family today, especially the one I''ve been finding hard to love.', 'family', true),
  ('p27', 'Jesus, help me really listen at home tonight, instead of just waiting to speak.', 'family', true),
  ('p28', 'Lord, help me do today''s work honestly and well, and then let it go.', 'work', true),
  ('p29', 'God, give me kindness for the people I work with, especially when the day runs long.', 'work', true),
  ('p30', 'Father, when my work feels small or unseen, remind me that it still matters to you.', 'work', true),
  ('p31', 'Jesus, make me quicker to be kind today than to be right.', 'general', true),
  ('p32', 'God, I don''t have the words right now. Meet me here anyway.', 'general', true)
insert into reflection_prompts (key, text, context, is_active) values
  ('r01', 'What is one thing from today''s quest you''d like to carry with you?', 'after_quest', true),
  ('r02', 'Was there a moment in this quest that slowed you down, in a good way?', 'after_quest', true),
  ('r03', 'What surprised you as you walked through this step?', 'after_quest', true),
  ('r04', 'If you shared one thing from today''s quest with a friend, what would it be?', 'after_quest', true),
  ('r05', 'Which word or phrase stayed with you after the reading ended?', 'after_scripture', true),
  ('r06', 'Where does this passage meet something you''re living right now?', 'after_scripture', true),
  ('r07', 'If you could sit with the writer of these verses, what would you ask?', 'after_scripture', true),
  ('r08', 'What part of this passage would you like to return to tomorrow?', 'after_scripture', true),
  ('r09', 'What did you notice in the quiet, before or after the words?', 'after_prayer', true),
  ('r10', 'Is there something you didn''t say in prayer that you''d like to name here?', 'after_prayer', true),
  ('r11', 'How do you feel now, compared to when you began to pray?', 'after_prayer', true),
  ('r12', 'What are you leaving in God''s hands as you go?', 'after_prayer', true),
  ('r13', 'What would it look like to move through today a little more gently?', 'morning', true),
  ('r14', 'Who might need your patience today?', 'morning', true),
  ('r15', 'What small kindness could you carry into the hours ahead?', 'morning', true),
  ('r16', 'As the day begins, what do you hope to remember by evening?', 'morning', true),
  ('r17', 'Looking back, where did today feel most alive?', 'evening', true),
  ('r18', 'What moment from today deserves a second look before you rest?', 'evening', true),
  ('r19', 'What small mercy almost went unnoticed today?', 'evening', true),
  ('r20', 'What can you set down before you sleep?', 'evening', true),
  ('r21', 'What is something ordinary you would miss if it were gone?', 'gratitude', true),
  ('r22', 'Who has been kind to you lately, in ways big or small?', 'gratitude', true),
  ('r23', 'What good thing came to you today that you didn''t ask for?', 'gratitude', true),
  ('r24', 'When did you last feel simply glad — and what was happening?', 'gratitude', true),
  ('r25', 'What feels heavy to carry right now?', 'difficulty', true),
  ('r26', 'If your worry could speak plainly, what would it say?', 'difficulty', true),
  ('r27', 'What kind of help would actually help today?', 'difficulty', true),
  ('r28', 'Where do you need mercy right now — from God, from others, or from yourself?', 'difficulty', true),
  ('r29', 'What are you noticing about yourself in this season?', 'general', true),
  ('r30', 'What question have you been living with lately?', 'general', true),
  ('r31', 'What would real rest look like for you this week?', 'general', true),
  ('r32', 'What would you like to begin again?', 'general', true)
insert into daily_verses (reference, book_slug, chapter, verse_start, verse_end, text, theme, is_active) values
  ('John 3:16', 'john', 3, 16, 16, 'For God so loved the world, that he gave his one and only Son, that whoever believes in him should not perish, but have eternal life.', 'love', true),
  ('Psalm 23:1-3', 'psalms', 23, 1, 3, 'Yahweh is my shepherd: I shall lack nothing. He makes me lie down in green pastures. He leads me beside still waters. He restores my soul. He guides me in the paths of righteousness for his name’s sake.', 'rest', true),
  ('Psalm 46:10', 'psalms', 46, 10, 10, '“Be still, and know that I am God. I will be exalted among the nations. I will be exalted in the earth.”', 'stillness', true),
  ('Isaiah 40:31', 'isaiah', 40, 31, 31, 'but those who wait for Yahweh will renew their strength. They will mount up with wings like eagles. They will run, and not be weary. They will walk, and not faint.', 'renewal', true),
  ('Isaiah 41:10', 'isaiah', 41, 10, 10, 'Don’t you be afraid, for I am with you. Don’t be dismayed, for I am your God. I will strengthen you. Yes, I will help you. Yes, I will uphold you with the right hand of my righteousness.', 'courage', true),
  ('Isaiah 26:3', 'isaiah', 26, 3, 3, 'You will keep whoever’s mind is steadfast in perfect peace, because he trusts in you.', 'peace', true),
  ('Jeremiah 29:11', 'jeremiah', 29, 11, 11, 'For I know the thoughts that I think toward you,” says Yahweh, “thoughts of peace, and not of evil, to give you hope and a future.', 'hope', true),
  ('Matthew 5:14-16', 'matthew', 5, 14, 16, 'You are the light of the world. A city located on a hill can’t be hidden. Neither do you light a lamp, and put it under a measuring basket, but on a stand; and it shines to all who are in the house. Even so, let your light shine before men; that they may see your good works, and glorify your Father who is in heaven.', 'kindness', true),
  ('Matthew 6:33-34', 'matthew', 6, 33, 34, 'But seek first God’s Kingdom, and his righteousness; and all these things will be given to you as well. Therefore don’t be anxious for tomorrow, for tomorrow will be anxious for itself. Each day’s own evil is sufficient.', 'trust', true),
  ('Matthew 11:28-30', 'matthew', 11, 28, 30, '“Come to me, all you who labor and are heavily burdened, and I will give you rest. Take my yoke upon you, and learn from me, for I am gentle and humble in heart; and you will find rest for your souls. For my yoke is easy, and my burden is light.”', 'rest', true),
  ('Matthew 22:37-39', 'matthew', 22, 37, 39, 'Jesus said to him, “ ‘You shall love the Lord your God with all your heart, with all your soul, and with all your mind.’ This is the first and great commandment. A second likewise is this, ‘You shall love your neighbor as yourself.’', 'love', true),
  ('Matthew 7:7-8', 'matthew', 7, 7, 8, '“Ask, and it will be given you. Seek, and you will find. Knock, and it will be opened for you. For everyone who asks receives. He who seeks finds. To him who knocks it will be opened.', 'prayer', true),
  ('Philippians 4:6-7', 'philippians', 4, 6, 7, 'In nothing be anxious, but in everything, by prayer and petition with thanksgiving, let your requests be made known to God. And the peace of God, which surpasses all understanding, will guard your hearts and your thoughts in Christ Jesus.', 'peace', true),
  ('Philippians 4:13', 'philippians', 4, 13, 13, 'I can do all things through Christ, who strengthens me.', 'courage', true),
  ('Romans 8:28', 'romans', 8, 28, 28, 'We know that all things work together for good for those who love God, for those who are called according to his purpose.', 'trust', true),
  ('Romans 8:38-39', 'romans', 8, 38, 39, 'For I am persuaded that neither death, nor life, nor angels, nor principalities, nor things present, nor things to come, nor powers, nor height, nor depth, nor any other created thing will be able to separate us from God’s love which is in Christ Jesus our Lord.', 'love', true),
  ('Romans 12:12', 'romans', 12, 12, 12, 'rejoicing in hope; enduring in troubles; continuing steadfastly in prayer;', 'hope', true),
  ('Romans 15:13', 'romans', 15, 13, 13, 'Now may the God of hope fill you with all joy and peace in believing, that you may abound in hope, in the power of the Holy Spirit.', 'hope', true),
  ('Joshua 1:9', 'joshua', 1, 9, 9, 'Haven’t I commanded you? Be strong and courageous. Don’t be afraid. Don’t be dismayed, for Yahweh your God is with you wherever you go.”', 'courage', true),
  ('Proverbs 3:5-6', 'proverbs', 3, 5, 6, 'Trust in Yahweh with all your heart, and don’t lean on your own understanding. In all your ways acknowledge him, and he will make your paths straight.', 'trust', true),
  ('Proverbs 16:3', 'proverbs', 16, 3, 3, 'Commit your deeds to Yahweh, and your plans shall succeed.', 'work', true),
  ('Psalm 118:24', 'psalms', 118, 24, 24, 'This is the day that Yahweh has made. We will rejoice and be glad in it!', 'gratitude', true),
  ('Psalm 121:1-2', 'psalms', 121, 1, 2, 'I will lift up my eyes to the hills. Where does my help come from? My help comes from Yahweh, who made heaven and earth.', 'trust', true),
  ('Psalm 139:23-24', 'psalms', 139, 23, 24, 'Search me, God, and know my heart. Try me, and know my thoughts. See if there is any wicked way in me, and lead me in the everlasting way.', 'honesty', true),
  ('Lamentations 3:22-23', 'lamentations', 3, 22, 23, 'It is because of Yahweh’s loving kindnesses that we are not consumed, because his compassion doesn’t fail. They are new every morning. Great is your faithfulness.', 'renewal', true),
  ('Micah 6:8', 'micah', 6, 8, 8, 'He has shown you, O man, what is good. What does Yahweh require of you, but to act justly, to love mercy, and to walk humbly with your God?', 'justice', true),
  ('Zephaniah 3:17', 'zephaniah', 3, 17, 17, 'Yahweh, your God, is among you, a mighty one who will save. He will rejoice over you with joy. He will calm you in his love. He will rejoice over you with singing.', 'love', true),
  ('Galatians 5:22-23', 'galatians', 5, 22, 23, 'But the fruit of the Spirit is love, joy, peace, patience, kindness, goodness, faith, gentleness, and self-control. Against such things there is no law.', 'growth', true),
  ('Galatians 6:9', 'galatians', 6, 9, 9, 'Let’s not be weary in doing good, for we will reap in due season, if we don’t give up.', 'perseverance', true),
  ('Ephesians 2:8-10', 'ephesians', 2, 8, 10, 'for by grace you have been saved through faith, and that not of yourselves; it is the gift of God, not of works, that no one would boast. For we are his workmanship, created in Christ Jesus for good works, which God prepared before that we would walk in them.', 'grace', true),
  ('Ephesians 4:32', 'ephesians', 4, 32, 32, 'And be kind to one another, tender hearted, forgiving each other, just as God also in Christ forgave you.', 'forgiveness', true),
  ('Colossians 3:12', 'colossians', 3, 12, 12, 'Put on therefore, as God’s chosen ones, holy and beloved, a heart of compassion, kindness, lowliness, humility, and perseverance;', 'kindness', true),
  ('Colossians 3:23', 'colossians', 3, 23, 23, 'And whatever you do, work heartily, as for the Lord, and not for men,', 'work', true),
  ('1 Thessalonians 5:11', '1-thessalonians', 5, 11, 11, 'Therefore exhort one another, and build each other up, even as you also do.', 'encouragement', true),
  ('1 Thessalonians 5:16-18', '1-thessalonians', 5, 16, 18, 'Always rejoice. Pray without ceasing. In everything give thanks, for this is the will of God in Christ Jesus toward you.', 'gratitude', true),
  ('Hebrews 10:24-25', 'hebrews', 10, 24, 25, 'Let’s consider how to provoke one another to love and good works, not forsaking our own assembling together, as the custom of some is, but exhorting one another, and so much the more as you see the Day approaching.', 'community', true),
  ('Hebrews 11:1', 'hebrews', 11, 1, 1, 'Now faith is assurance of things hoped for, proof of things not seen.', 'faith', true),
  ('James 1:19', 'james', 1, 19, 19, 'So, then, my beloved brothers, let every man be swift to hear, slow to speak, and slow to anger;', 'patience', true),
  ('James 1:22', 'james', 1, 22, 22, 'But be doers of the word, and not only hearers, deluding your own selves.', 'action', true),
  ('James 4:8', 'james', 4, 8, 8, 'Draw near to God, and he will draw near to you. Cleanse your hands, you sinners. Purify your hearts, you double-minded.', 'prayer', true),
  ('1 Peter 5:7', '1-peter', 5, 7, 7, 'casting all your worries on him, because he cares for you.', 'rest', true),
  ('1 John 4:7', '1-john', 4, 7, 7, 'Beloved, let’s love one another, for love is of God; and everyone who loves has been born of God, and knows God.', 'love', true),
  ('1 John 4:19', '1-john', 4, 19, 19, 'We love him, because he first loved us.', 'love', true),
  ('Psalm 27:1', 'psalms', 27, 1, 1, 'Yahweh is my light and my salvation. Whom shall I fear? Yahweh is the strength of my life. Of whom shall I be afraid?', 'courage', true),
  ('Psalm 34:8', 'psalms', 34, 8, 8, 'Oh taste and see that Yahweh is good. Blessed is the man who takes refuge in him.', 'gratitude', true),
  ('Psalm 51:10', 'psalms', 51, 10, 10, 'Create in me a clean heart, O God. Renew a right spirit within me.', 'renewal', true),
  ('Psalm 90:12', 'psalms', 90, 12, 12, 'So teach us to count our days, that we may gain a heart of wisdom.', 'wisdom', true),
  ('Psalm 103:2-4', 'psalms', 103, 2, 4, 'Praise Yahweh, my soul, and don’t forget all his benefits, who forgives all your sins, who heals all your diseases, who redeems your life from destruction, who crowns you with loving kindness and tender mercies,', 'gratitude', true),
  ('Psalm 19:14', 'psalms', 19, 14, 14, 'Let the words of my mouth and the meditation of my heart be acceptable in your sight, Yahweh, my rock, and my redeemer.', 'prayer', true),
  ('Mark 12:30-31', 'mark', 12, 30, 31, 'you shall love the Lord your God with all your heart, and with all your soul, and with all your mind, and with all your strength.’ This is the first commandment. The second is like this, ‘You shall love your neighbor as yourself.’ There is no other commandment greater than these.”', 'love', true),
  ('Luke 6:31', 'luke', 6, 31, 31, '“As you would like people to do to you, do exactly so to them.', 'kindness', true),
  ('Luke 12:34', 'luke', 12, 34, 34, 'For where your treasure is, there will your heart be also.', 'treasure', true),
  ('John 1:5', 'john', 1, 5, 5, 'The light shines in the darkness, and the darkness hasn’t overcome it.', 'hope', true),
  ('John 13:34-35', 'john', 13, 34, 35, 'A new commandment I give to you, that you love one another. Just as I have loved you, you also love one another. By this everyone will know that you are my disciples, if you have love for one another.”', 'love', true),
  ('John 14:27', 'john', 14, 27, 27, 'Peace I leave with you. My peace I give to you; not as the world gives, I give to you. Don’t let your heart be troubled, neither let it be fearful.', 'peace', true),
  ('John 15:5', 'john', 15, 5, 5, 'I am the vine. You are the branches. He who remains in me and I in him bears much fruit, for apart from me you can do nothing.', 'growth', true),
  ('1 Corinthians 13:4-7', '1-corinthians', 13, 4, 7, 'Love is patient and is kind. Love doesn’t envy. Love doesn’t brag, is not proud, doesn’t behave itself inappropriately, doesn’t seek its own way, is not provoked, takes no account of evil; doesn’t rejoice in unrighteousness, but rejoices with the truth; bears all things, believes all things, hopes all things, and endures all things.', 'love', true),
  ('1 Corinthians 16:14', '1-corinthians', 16, 14, 14, 'Let all that you do be done in love.', 'love', true),
  ('2 Corinthians 5:17', '2-corinthians', 5, 17, 17, 'Therefore if anyone is in Christ, he is a new creation. The old things have passed away. Behold, all things have become new.', 'renewal', true),
  ('Deuteronomy 31:8', 'deuteronomy', 31, 8, 8, 'Yahweh himself is who goes before you. He will be with you. He will not fail you nor forsake you. Don’t be afraid. Don’t be discouraged.”', 'courage', true),
  ('Genesis 1:27', 'genesis', 1, 27, 27, 'God created man in his own image. In God’s image he created him; male and female he created them.', 'dignity', true),
  ('Genesis 50:20', 'genesis', 50, 20, 20, 'As for you, you meant evil against me, but God meant it for good, to save many people alive, as is happening today.', 'providence', true),
  ('Exodus 3:14', 'exodus', 3, 14, 14, 'God said to Moses, “I AM WHO I AM,” and he said, “You shall tell the children of Israel this: ‘I AM has sent me to you.’ ”', 'presence', true),
  ('Exodus 33:14', 'exodus', 33, 14, 14, 'He said, “My presence will go with you, and I will give you rest.”', 'rest', true),
  ('Leviticus 19:18', 'leviticus', 19, 18, 18, '“ ‘You shall not take vengeance, nor bear any grudge against the children of your people; but you shall love your neighbor as yourself. I am Yahweh.', 'love', true),
  ('Leviticus 19:34', 'leviticus', 19, 34, 34, 'The stranger who lives as a foreigner with you shall be to you as the native-born among you, and you shall love him as yourself; for you lived as foreigners in the land of Egypt. I am Yahweh your God.', 'welcome', true),
  ('Numbers 6:24-26', 'numbers', 6, 24, 26, '‘Yahweh bless you, and keep you. Yahweh make his face to shine on you, and be gracious to you. Yahweh lift up his face toward you, and give you peace.’', 'blessing', true),
  ('Numbers 23:19', 'numbers', 23, 19, 19, 'God is not a man, that he should lie, nor a son of man, that he should repent. Has he said, and will he not do it? Or has he spoken, and will he not make it good?', 'faithfulness', true),
  ('Deuteronomy 6:5', 'deuteronomy', 6, 5, 5, 'You shall love Yahweh your God with all your heart, with all your soul, and with all your might.', 'love', true),
  ('Deuteronomy 30:19-20', 'deuteronomy', 30, 19, 20, 'I call heaven and earth to witness against you today that I have set before you life and death, the blessing and the curse. Therefore choose life, that you may live, you and your descendants, to love Yahweh your God, to obey his voice, and to cling to him; for he is your life, and the length of your days, that you may dwell in the land which Yahweh swore to your fathers, to Abraham, to Isaac, and to Jacob, to give them.', 'choice', true),
  ('Joshua 24:15', 'joshua', 24, 15, 15, 'If it seems evil to you to serve Yahweh, choose today whom you will serve; whether the gods which your fathers served that were beyond the River, or the gods of the Amorites, in whose land you dwell; but as for me and my house, we will serve Yahweh.”', 'commitment', true),
  ('Joshua 4:24', 'joshua', 4, 24, 24, 'that all the peoples of the earth may know that Yahweh’s hand is mighty, and that you may fear Yahweh your God forever.’ ”', 'witness', true),
  ('Judges 6:12', 'judges', 6, 12, 12, 'Yahweh’s angel appeared to him, and said to him, “Yahweh is with you, you mighty man of valor!”', 'courage', true),
  ('Judges 8:23', 'judges', 8, 23, 23, 'Gideon said to them, “I will not rule over you, neither shall my son rule over you. Yahweh shall rule over you.”', 'humility', true),
  ('Ruth 1:16-17', 'ruth', 1, 16, 17, 'Ruth said, “Don’t urge me to leave you, and to return from following you, for where you go, I will go; and where you stay, I will stay. Your people will be my people, and your God my God. Where you die, I will die, and there I will be buried. May Yahweh do so to me, and more also, if anything but death parts you and me.”', 'faithfulness', true),
  ('Ruth 2:12', 'ruth', 2, 12, 12, 'May Yahweh repay your work, and a full reward be given to you from Yahweh, the God of Israel, under whose wings you have come to take refuge.”', 'refuge', true),
  ('1 Samuel 3:10', '1-samuel', 3, 10, 10, 'Yahweh came, and stood, and called as at other times, “Samuel! Samuel!” Then Samuel said, “Speak; for your servant hears.”', 'listening', true),
  ('1 Samuel 16:7', '1-samuel', 16, 7, 7, 'But Yahweh said to Samuel, “Don’t look on his face, or on the height of his stature, because I have rejected him; for I don’t see as man sees. For man looks at the outward appearance, but Yahweh looks at the heart.”', 'character', true),
  ('2 Samuel 22:2-3', '2-samuel', 22, 2, 3, 'and he said: “Yahweh is my rock, my fortress, and my deliverer, even mine; God is my rock in whom I take refuge; my shield, and the horn of my salvation, my high tower, and my refuge. My savior, you save me from violence.', 'refuge', true),
  ('2 Samuel 7:22', '2-samuel', 7, 22, 22, 'Therefore you are great, Yahweh God. For there is no one like you, neither is there any God besides you, according to all that we have heard with our ears.', 'worship', true),
  ('1 Kings 8:61', '1-kings', 8, 61, 61, '“Let your heart therefore be perfect with Yahweh our God, to walk in his statutes, and to keep his commandments, as it is today.”', 'devotion', true),
  ('1 Kings 19:12', '1-kings', 19, 12, 12, 'After the earthquake a fire passed; but Yahweh was not in the fire. After the fire, there was a still small voice.', 'stillness', true),
  ('2 Kings 6:16-17', '2-kings', 6, 16, 17, 'He answered, “Don’t be afraid; for those who are with us are more than those who are with them.” Elisha prayed, and said, “Yahweh, please open his eyes, that he may see.” Yahweh opened the young man’s eyes; and he saw: and behold, the mountain was full of horses and chariots of fire around Elisha.', 'courage', true),
  ('2 Kings 20:5', '2-kings', 20, 5, 5, '“Turn back, and tell Hezekiah the prince of my people, ‘Yahweh, the God of David your father, says, “I have heard your prayer. I have seen your tears. Behold, I will heal you. On the third day, you will go up to Yahweh’s house.', 'healing', true),
  ('1 Chronicles 16:11', '1-chronicles', 16, 11, 11, 'Seek Yahweh and his strength. Seek his face forever more.', 'prayer', true),
  ('1 Chronicles 16:34', '1-chronicles', 16, 34, 34, 'Oh give thanks to Yahweh, for he is good, for his loving kindness endures forever.', 'gratitude', true),
  ('2 Chronicles 15:7', '2-chronicles', 15, 7, 7, 'But you be strong, and don’t let your hands be slack; for your work will be rewarded.”', 'perseverance', true),
  ('2 Chronicles 20:12', '2-chronicles', 20, 12, 12, 'Our God, will you not judge them? For we have no might against this great company that comes against us. We don’t know what to do, but our eyes are on you.”', 'dependence', true),
  ('Ezra 7:10', 'ezra', 7, 10, 10, 'For Ezra had set his heart to seek Yahweh’s law, and to do it, and to teach statutes and ordinances in Israel.', 'scripture', true),
  ('Ezra 10:4', 'ezra', 10, 4, 4, 'Arise; for the matter belongs to you, and we are with you. Be courageous, and do it.”', 'courage', true),
  ('Nehemiah 4:14', 'nehemiah', 4, 14, 14, 'I looked, and rose up, and said to the nobles, to the rulers, and to the rest of the people, “Don’t be afraid of them! Remember the Lord, who is great and awesome, and fight for your brothers, your sons, your daughters, your wives, and your houses.”', 'courage', true),
  ('Nehemiah 8:10', 'nehemiah', 8, 10, 10, 'Then he said to them, “Go your way. Eat the fat, drink the sweet, and send portions to him for whom nothing is prepared, for today is holy to our Lord. Don’t be grieved, for the joy of Yahweh is your strength.”', 'joy', true),
  ('Esther 4:14', 'esther', 4, 14, 14, 'For if you remain silent now, then relief and deliverance will come to the Jews from another place, but you and your father’s house will perish. Who knows if you haven’t come to the kingdom for such a time as this?”', 'purpose', true),
  ('Esther 8:16', 'esther', 8, 16, 16, 'The Jews had light, gladness, joy, and honor.', 'joy', true),
  ('Job 19:25', 'job', 19, 25, 25, 'But as for me, I know that my Redeemer lives. In the end, he will stand upon the earth.', 'hope', true),
  ('Job 28:28', 'job', 28, 28, 28, 'To man he said, ‘Behold, the fear of the Lord, that is wisdom. To depart from evil is understanding.’ ”', 'wisdom', true),
  ('Psalm 1:1-3', 'psalms', 1, 1, 3, 'Blessed is the man who doesn’t walk in the counsel of the wicked, nor stand on the path of sinners, nor sit in the seat of scoffers; but his delight is in Yahweh’s law. On his law he meditates day and night. He will be like a tree planted by the streams of water, that produces its fruit in its season, whose leaf also does not wither. Whatever he does shall prosper.', 'growth', true),
  ('Psalm 16:11', 'psalms', 16, 11, 11, 'You will show me the path of life. In your presence is fullness of joy. In your right hand there are pleasures forever more.', 'joy', true),
  ('Proverbs 4:23', 'proverbs', 4, 23, 23, 'Keep your heart with all diligence, for out of it is the wellspring of life.', 'attention', true),
  ('Proverbs 11:25', 'proverbs', 11, 25, 25, 'The liberal soul shall be made fat. He who waters shall be watered also himself.', 'generosity', true),
  ('Ecclesiastes 3:1', 'ecclesiastes', 3, 1, 1, 'For everything there is a season, and a time for every purpose under heaven:', 'seasons', true),
  ('Ecclesiastes 4:9-10', 'ecclesiastes', 4, 9, 10, 'Two are better than one, because they have a good reward for their labor. For if they fall, the one will lift up his fellow; but woe to him who is alone when he falls, and doesn’t have another to lift him up.', 'community', true),
  ('Song of Solomon 2:10-12', 'song-of-solomon', 2, 10, 12, 'My beloved spoke, and said to me, “Rise up, my love, my beautiful one, and come away. For behold, the winter is past. The rain is over and gone. The flowers appear on the earth. The time of the singing has come, and the voice of the turtledove is heard in our land.', 'renewal', true),
  ('Song of Solomon 8:6-7', 'song-of-solomon', 8, 6, 7, 'Set me as a seal on your heart, as a seal on your arm; for love is strong as death. Jealousy is as cruel as Sheol. Its flashes are flashes of fire, a very flame of Yahweh. Many waters can’t quench love, neither can floods drown it. If a man would give all the wealth of his house for love, he would be utterly scorned.', 'love', true),
  ('Isaiah 6:8', 'isaiah', 6, 8, 8, 'I heard the Lord’s voice, saying, “Whom shall I send, and who will go for us?” Then I said, “Here I am. Send me!”', 'calling', true),
  ('Isaiah 58:6-7', 'isaiah', 58, 6, 7, '“Isn’t this the fast that I have chosen: to release the bonds of wickedness, to undo the straps of the yoke, to let the oppressed go free, and that you break every yoke? Isn’t it to distribute your bread to the hungry, and that you bring the poor who are cast out to your house? When you see the naked, that you cover him; and that you not hide yourself from your own flesh?', 'justice', true),
  ('Jeremiah 6:16', 'jeremiah', 6, 16, 16, 'Yahweh says, “Stand in the ways and see, and ask for the old paths, ‘Where is the good way?’ and walk in it, and you will find rest for your souls. But they said, ‘We will not walk in it.’', 'wisdom', true),
  ('Jeremiah 31:3', 'jeremiah', 31, 3, 3, 'Yahweh appeared of old to me, saying, “Yes, I have loved you with an everlasting love. Therefore I have drawn you with loving kindness.', 'love', true),
  ('Lamentations 3:25-26', 'lamentations', 3, 25, 26, 'Yahweh is good to those who wait for him, to the soul who seeks him. It is good that a man should hope and quietly wait for the salvation of Yahweh.', 'patience', true),
  ('Lamentations 5:21', 'lamentations', 5, 21, 21, 'Turn us to yourself, Yahweh, and we will be turned. Renew our days as of old.', 'renewal', true),
  ('Ezekiel 11:19', 'ezekiel', 11, 19, 19, 'I will give them one heart, and I will put a new spirit within you. I will take the stony heart out of their flesh, and will give them a heart of flesh;', 'renewal', true),
  ('Ezekiel 36:26', 'ezekiel', 36, 26, 26, 'I will also give you a new heart, and I will put a new spirit within you. I will take away the stony heart out of your flesh, and I will give you a heart of flesh.', 'renewal', true),
  ('Daniel 3:17-18', 'daniel', 3, 17, 18, 'If it happens, our God whom we serve is able to deliver us from the burning fiery furnace; and he will deliver us out of your hand, O king. But if not, let it be known to you, O king, that we will not serve your gods or worship the golden image which you have set up.”', 'courage', true),
  ('Daniel 6:10', 'daniel', 6, 10, 10, 'When Daniel knew that the writing was signed, he went into his house (now his windows were open in his room toward Jerusalem) and he kneeled on his knees three times a day, and prayed, and gave thanks before his God, as he did before.', 'prayer', true),
  ('Hosea 6:6', 'hosea', 6, 6, 6, 'For I desire mercy, and not sacrifice; and the knowledge of God more than burnt offerings.', 'mercy', true),
  ('Hosea 10:12', 'hosea', 10, 12, 12, 'Sow to yourselves in righteousness, reap according to kindness. Break up your fallow ground; for it is time to seek Yahweh, until he comes and rains righteousness on you.', 'renewal', true),
  ('Joel 2:12-13', 'joel', 2, 12, 13, '“Yet even now,” says Yahweh, “turn to me with all your heart, and with fasting, and with weeping, and with mourning.” Tear your heart, and not your garments, and turn to Yahweh, your God; for he is gracious and merciful, slow to anger, and abundant in loving kindness, and relents from sending calamity.', 'repentance', true),
  ('Joel 2:28', 'joel', 2, 28, 28, '“It will happen afterward, that I will pour out my Spirit on all flesh; and your sons and your daughters will prophesy. Your old men will dream dreams. Your young men will see visions.', 'spirit', true),
  ('Amos 5:14', 'amos', 5, 14, 14, 'Seek good, and not evil, that you may live; and so Yahweh, the God of Armies, will be with you, as you say.', 'goodness', true),
  ('Amos 5:24', 'amos', 5, 24, 24, 'But let justice roll on like rivers, and righteousness like a mighty stream.', 'justice', true),
  ('Obadiah 1:15', 'obadiah', 1, 15, 15, 'For the day of Yahweh is near all the nations! As you have done, it will be done to you. Your deeds will return upon your own head.', 'justice', true),
  ('Obadiah 1:17', 'obadiah', 1, 17, 17, 'But in Mount Zion, there will be those who escape, and it will be holy. The house of Jacob will possess their possessions.', 'deliverance', true),
  ('Jonah 2:2', 'jonah', 2, 2, 2, 'He said, “I called because of my affliction to Yahweh. He answered me. Out of the belly of Sheol I cried. You heard my voice.', 'prayer', true),
  ('Jonah 3:10', 'jonah', 3, 10, 10, 'God saw their works, that they turned from their evil way. God relented of the disaster which he said he would do to them, and he didn’t do it.', 'mercy', true),
  ('Micah 4:4', 'micah', 4, 4, 4, 'But they will sit every man under his vine and under his fig tree; and no one will make them afraid: For the mouth of Yahweh of Armies has spoken.', 'peace', true),
  ('Micah 7:18', 'micah', 7, 18, 18, 'Who is a God like you, who pardons iniquity, and passes over the disobedience of the remnant of his heritage? He doesn’t retain his anger forever, because he delights in loving kindness.', 'mercy', true),
  ('Nahum 1:7', 'nahum', 1, 7, 7, 'Yahweh is good, a stronghold in the day of trouble; and he knows those who take refuge in him.', 'refuge', true),
  ('Nahum 2:2', 'nahum', 2, 2, 2, 'For Yahweh restores the excellency of Jacob, as the excellency of Israel; for the destroyers have destroyed them, and ruined their vine branches.', 'restoration', true),
  ('Habakkuk 2:4', 'habakkuk', 2, 4, 4, 'Behold, his soul is puffed up. It is not upright in him, but the righteous will live by his faith.', 'faith', true),
  ('Habakkuk 3:19', 'habakkuk', 3, 19, 19, 'Yahweh, the Lord, is my strength. He makes my feet like deer’s feet, and enables me to go in high places. For the music director, on my stringed instruments.', 'strength', true),
  ('Zephaniah 2:3', 'zephaniah', 2, 3, 3, 'Seek Yahweh, all you humble of the land, who have kept his ordinances. Seek righteousness. Seek humility. It may be that you will be hidden in the day of Yahweh’s anger.', 'humility', true),
  ('Zephaniah 3:9', 'zephaniah', 3, 9, 9, 'For then I will purify the lips of the peoples, that they may all call on Yahweh’s name, to serve him shoulder to shoulder.', 'worship', true),
  ('Haggai 1:5', 'haggai', 1, 5, 5, 'Now therefore this is what Yahweh of Armies says: Consider your ways.', 'reflection', true),
  ('Haggai 2:9', 'haggai', 2, 9, 9, '‘The latter glory of this house will be greater than the former,’ says Yahweh of Armies; ‘and in this place I will give peace,’ says Yahweh of Armies.”', 'peace', true),
  ('Zechariah 4:6', 'zechariah', 4, 6, 6, 'Then he answered and spoke to me, saying, “This is Yahweh’s word to Zerubbabel, saying, ‘Not by might, nor by power, but by my Spirit,’ says Yahweh of Armies.', 'spirit', true),
  ('Zechariah 8:16-17', 'zechariah', 8, 16, 17, 'These are the things that you shall do: speak every man the truth with his neighbor. Execute the judgment of truth and peace in your gates, and let none of you devise evil in your hearts against his neighbor, and love no false oath: for all these are things that I hate,” says Yahweh.', 'truth', true),
  ('Malachi 3:10', 'malachi', 3, 10, 10, 'Bring the whole tithe into the storehouse, that there may be food in my house, and test me now in this,” says Yahweh of Armies, “if I will not open you the windows of heaven, and pour you out a blessing, that there will not be room enough for.', 'trust', true),
  ('Malachi 4:2', 'malachi', 4, 2, 2, 'But to you who fear my name shall the sun of righteousness arise with healing in its wings. You will go out, and leap like calves of the stall.', 'healing', true),
  ('Matthew 5:9', 'matthew', 5, 9, 9, 'Blessed are the peacemakers, for they shall be called children of God.', 'peacemaking', true),
  ('Matthew 25:40', 'matthew', 25, 40, 40, '“The King will answer them, ‘Most certainly I tell you, because you did it to one of the least of these my brothers, you did it to me.’', 'service', true),
  ('Mark 9:24', 'mark', 9, 24, 24, 'Immediately the father of the child cried out with tears, “I believe. Help my unbelief!”', 'faith', true),
  ('Mark 10:45', 'mark', 10, 45, 45, 'For the Son of Man also came not to be served, but to serve, and to give his life as a ransom for many.”', 'service', true),
  ('Luke 4:18', 'luke', 4, 18, 18, '“The Spirit of the Lord is on me, because he has anointed me to preach good news to the poor. He has sent me to heal the broken hearted, to proclaim release to the captives, recovering of sight to the blind, to deliver those who are crushed,', 'justice', true),
  ('Luke 10:27', 'luke', 10, 27, 27, 'He answered, “You shall love the Lord your God with all your heart, with all your soul, with all your strength, and with all your mind; and your neighbor as yourself.”', 'love', true),
  ('John 8:12', 'john', 8, 12, 12, 'Again, therefore, Jesus spoke to them, saying, “I am the light of the world. He who follows me will not walk in the darkness, but will have the light of life.”', 'light', true),
  ('John 10:10', 'john', 10, 10, 10, 'The thief only comes to steal, kill, and destroy. I came that they may have life, and may have it abundantly.', 'life', true),
  ('Acts 1:8', 'acts', 1, 8, 8, 'But you will receive power when the Holy Spirit has come upon you. You will be witnesses to me in Jerusalem, in all Judea and Samaria, and to the uttermost parts of the earth.”', 'witness', true),
  ('Acts 2:42', 'acts', 2, 42, 42, 'They continued steadfastly in the apostles’ teaching and fellowship, in the breaking of bread, and prayer.', 'community', true),
  ('Romans 5:8', 'romans', 5, 8, 8, 'But God commends his own love toward us, in that while we were yet sinners, Christ died for us.', 'love', true),
  ('Romans 12:2', 'romans', 12, 2, 2, 'Don’t be conformed to this world, but be transformed by the renewing of your mind, so that you may prove what is the good, well-pleasing, and perfect will of God.', 'renewal', true),
  ('1 Corinthians 10:31', '1-corinthians', 10, 31, 31, 'Whether therefore you eat, or drink, or whatever you do, do all to the glory of God.', 'worship', true),
  ('1 Corinthians 12:26', '1-corinthians', 12, 26, 26, 'When one member suffers, all the members suffer with it. When one member is honored, all the members rejoice with it.', 'solidarity', true),
  ('2 Corinthians 4:7-9', '2-corinthians', 4, 7, 9, 'But we have this treasure in clay vessels, that the exceeding greatness of the power may be of God, and not from ourselves. We are pressed on every side, yet not crushed; perplexed, yet not to despair; pursued, yet not forsaken; struck down, yet not destroyed;', 'perseverance', true),
  ('2 Corinthians 12:9', '2-corinthians', 12, 9, 9, 'He has said to me, “My grace is sufficient for you, for my power is made perfect in weakness.” Most gladly therefore I will rather glory in my weaknesses, that the power of Christ may rest on me.', 'grace', true),
  ('Galatians 2:20', 'galatians', 2, 20, 20, 'I have been crucified with Christ, and it is no longer I who live, but Christ lives in me. That life which I now live in the flesh, I live by faith in the Son of God, who loved me, and gave himself up for me.', 'faith', true),
  ('Galatians 5:13', 'galatians', 5, 13, 13, 'For you, brothers, were called for freedom. Only don’t use your freedom for gain to the flesh, but through love be servants to one another.', 'service', true),
  ('Ephesians 3:20-21', 'ephesians', 3, 20, 21, 'Now to him who is able to do exceedingly abundantly above all that we ask or think, according to the power that works in us, to him be the glory in the assembly and in Christ Jesus to all generations forever and ever. Amen.', 'hope', true),
  ('Ephesians 6:10', 'ephesians', 6, 10, 10, 'Finally, be strong in the Lord, and in the strength of his might.', 'strength', true),
  ('Philippians 1:6', 'philippians', 1, 6, 6, 'being confident of this very thing, that he who began a good work in you will complete it until the day of Jesus Christ.', 'growth', true),
  ('Philippians 2:3-4', 'philippians', 2, 3, 4, 'doing nothing through rivalry or through conceit, but in humility, each counting others better than himself; each of you not just looking to his own things, but each of you also to the things of others.', 'humility', true),
  ('Colossians 1:16', 'colossians', 1, 16, 16, 'For by him all things were created in the heavens and on the earth, visible things and invisible things, whether thrones or dominions or principalities or powers. All things have been created through him and for him.', 'creation', true),
  ('Colossians 3:15', 'colossians', 3, 15, 15, 'And let the peace of God rule in your hearts, to which also you were called in one body, and be thankful.', 'peace', true),
  ('1 Thessalonians 4:11-12', '1-thessalonians', 4, 11, 12, 'and that you make it your ambition to lead a quiet life, and to do your own business, and to work with your own hands, even as we instructed you; that you may walk properly toward those who are outside, and may have need of nothing.', 'work', true),
  ('1 Thessalonians 5:21', '1-thessalonians', 5, 21, 21, 'Test all things, and hold firmly that which is good.', 'discernment', true),
  ('2 Thessalonians 1:3', '2-thessalonians', 1, 3, 3, 'We are bound to always give thanks to God for you, brothers, even as it is appropriate, because your faith grows exceedingly, and the love of each and every one of you toward one another abounds,', 'growth', true),
  ('2 Thessalonians 3:13', '2-thessalonians', 3, 13, 13, 'But you, brothers, don’t be weary in doing what is right.', 'perseverance', true),
  ('1 Timothy 4:12', '1-timothy', 4, 12, 12, 'Let no man despise your youth; but be an example to those who believe, in word, in your way of life, in love, in spirit, in faith, and in purity.', 'example', true),
  ('1 Timothy 6:6', '1-timothy', 6, 6, 6, 'But godliness with contentment is great gain.', 'contentment', true),
  ('2 Timothy 1:7', '2-timothy', 1, 7, 7, 'For God didn’t give us a spirit of fear, but of power, love, and self-control.', 'courage', true),
  ('Titus 3:4-5', 'titus', 3, 4, 5, 'But when the kindness of God our Savior and his love toward mankind appeared, not by works of righteousness which we did ourselves, but according to his mercy, he saved us through the washing of regeneration and renewing by the Holy Spirit,', 'grace', true),
  ('Philemon 1:6', 'philemon', 1, 6, 6, 'that the fellowship of your faith may become effective in the knowledge of every good thing which is in us in Christ Jesus.', 'faith', true),
  ('Hebrews 4:12', 'hebrews', 4, 12, 12, 'For the word of God is living and active, and sharper than any two-edged sword, piercing even to the dividing of soul and spirit, of both joints and marrow, and is able to discern the thoughts and intentions of the heart.', 'scripture', true),
  ('James 3:17', 'james', 3, 17, 17, 'But the wisdom that is from above is first pure, then peaceful, gentle, reasonable, full of mercy and good fruits, without partiality, and without hypocrisy.', 'wisdom', true),
  ('1 Peter 2:9', '1-peter', 2, 9, 9, 'But you are a chosen race, a royal priesthood, a holy nation, a people for God’s own possession, that you may proclaim the excellence of him who called you out of darkness into his marvelous light.', 'calling', true),
  ('2 Peter 1:3', '2-peter', 1, 3, 3, 'seeing that his divine power has granted to us all things that pertain to life and godliness, through the knowledge of him who called us by his own glory and virtue,', 'growth', true),
  ('1 John 1:9', '1-john', 1, 9, 9, 'If we confess our sins, he is faithful and righteous to forgive us the sins, and to cleanse us from all unrighteousness.', 'forgiveness', true),
  ('2 John 1:6', '2-john', 1, 6, 6, 'This is love, that we should walk according to his commandments. This is the commandment, even as you heard from the beginning, that you should walk in it.', 'love', true),
  ('3 John 1:4', '3-john', 1, 4, 4, 'I have no greater joy than this: to hear about my children walking in truth.', 'joy', true),
  ('Jude 1:24-25', 'jude', 1, 24, 25, 'Now to him who is able to keep them from stumbling, and to present you faultless before the presence of his glory in great joy, to God our Savior, who alone is wise, be glory and majesty, dominion and power, both now and forever. Amen.', 'hope', true),
  ('Revelation 21:4', 'revelation', 21, 4, 4, 'He will wipe away every tear from their eyes. Death will be no more; neither will there be mourning, nor crying, nor pain, any more. The first things have passed away.”', 'renewal', true)
insert into quest_templates (faith_provider_id, slug, title, category, duration_minutes, difficulty, energy_level, solo_or_social, indoor_or_outdoor, invitation, why_it_matters, scripture_reference, scripture_text_snapshot, reflection_prompt, prayer_prompt, growth_type, tags, season_tags, tradition_tags, sensitivity_tags, is_premium, is_active, review_status)
