  enabled = excluded.enabled;

-- Milestones
on conflict (key) do update set
  title = excluded.title, description = excluded.description,
  milestone_type = excluded.milestone_type,
  requirement_metric = excluded.requirement_metric,
  requirement_count = excluded.requirement_count, icon_key = excluded.icon_key,
  is_active = excluded.is_active;

-- Prayer prompts
on conflict (key) do update set text = excluded.text, category = excluded.category, is_active = excluded.is_active;

-- Reflection prompts
on conflict (key) do update set text = excluded.text, context = excluded.context, is_active = excluded.is_active;

-- Daily verse pool
on conflict (book_slug, chapter, verse_start, verse_end) do update set
