  theme = excluded.theme, is_active = excluded.is_active;

-- Quest templates (all launch quests remain spiritually complete and free)
select provider.id, value.slug, value.title, value.category, value.duration_minutes, value.difficulty, value.energy_level, value.solo_or_social, value.indoor_or_outdoor, value.invitation, value.why_it_matters, value.scripture_reference, value.scripture_text_snapshot, value.reflection_prompt, value.prayer_prompt, value.growth_type, value.tags, value.season_tags, value.tradition_tags, value.sensitivity_tags, value.is_premium, value.is_active, value.review_status
from faith_providers provider, (values
  ('pray-before-you-rise', 'Pray Before You Rise', 'prayer', 5, 'gentle', 'low', 'solo', 'indoor', 'Before you get up from your bed or couch, stay where you are a moment and offer God one honest sentence.', 'The first words of a day quietly shape it. Speaking to God before anything else is an old and simple way to begin.', 'Psalm 143:8', 'Cause me to hear your loving kindness in the morning, for I trust in you. Cause me to know the way in which I should walk, for I lift up my soul to you.', 'What was it like to speak to God before reaching for anything else?', 'God, be the first voice I turn to today.', 'roots', array['morning', 'rest', 'beginning' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('pray-for-three-people-by-name', 'Pray for Three People by Name', 'prayer', 10, 'gentle', 'low', 'solo', 'either', 'Bring three people to mind, one at a time, and ask God to be near each of them today.', 'Praying for others by name is one of the oldest works of love. It is a quiet way of carrying the people we care about.', 'Philippians 1:3-4', 'I thank my God whenever I remember you, always in every request of mine on behalf of you all, making my requests with joy,', 'Who came to mind that you did not expect?', 'Lord, hold the people I carried to you today.', 'roots', array['intercession', 'friendship', 'love' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('the-lords-prayer-slowly', 'The Lord''s Prayer, Slowly', 'prayer', 10, 'gentle', 'low', 'solo', 'either', 'Pray the Lord''s Prayer today one line at a time, pausing after each line to let it settle.', 'This is the prayer Jesus gave his friends to teach them how to pray. Praying it slowly lets old words become your own.', 'Matthew 6:9-13', 'Pray like this: ‘Our Father in heaven, may your name be kept holy. Let your Kingdom come. Let your will be done on earth as it is in heaven. Give us today our daily bread. Forgive us our debts, as we also forgive our debtors. Bring us not into temptation, but deliver us from the evil one. For yours is the Kingdom, the power, and the glory forever. Amen.’', 'Which line stayed with you the longest?', 'Father, teach me to pray.', 'roots', array['tradition', 'slowness', 'jesus' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('pray-while-you-walk', 'Pray While You Walk', 'prayer', 15, 'gentle', 'medium', 'solo', 'outdoor', 'Take a short walk today and turn what you notice along the way — a tree, a stranger, a worry — into simple prayer.', 'Prayer does not need a quiet room. Walking with God is one of the oldest shapes of pilgrimage, and it fits inside an ordinary day.', 'Psalm 19:1', 'The heavens declare the glory of God. The expanse shows his handiwork.', 'What did you see differently because you were praying?', 'Lord, open my eyes as I go.', 'roots', array['walking', 'creation', 'noticing' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('pray-for-someone-hard-to-love', 'Pray for Someone Hard to Love', 'prayer', 10, 'steady', 'low', 'solo', 'either', 'In the quiet of your own heart, ask God to bless one person you find hard to love.', 'Jesus asked his followers to pray for those who hurt them. This prayer is between you and God alone — it asks nothing else of you, and it can begin as small as a single sentence.', 'Matthew 5:44', 'But I tell you, love your enemies, bless those who curse you, do good to those who hate you, and pray for those who mistreat you and persecute you,', 'Did anything in you shift, even a little, as you prayed? It is all right if it did not.', 'Lord, soften what has gone hard in me.', 'roots', array['forgiveness', 'mercy', 'healing' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['forgiveness_sensitive', 'relationship_sensitive' ]::text[], false, true, 'approved'),
  ('carry-a-breath-prayer', 'Carry a Breath Prayer', 'prayer', 240, 'gentle', 'low', 'solo', 'either', 'Choose one short prayer — like "Lord, have mercy" or "You are with me" — and return to it gently through your afternoon.', 'Christians have prayed short phrases like this for centuries. A breath prayer keeps a small door open to God in the middle of ordinary hours.', '1 Thessalonians 5:17', 'Pray without ceasing.', 'When did the prayer return to you on its own?', 'Lord, stay near me through these ordinary hours.', 'roots', array['breath prayer', 'presence', 'work' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('five-minutes-of-silence', 'Five Minutes of Silence', 'silence', 5, 'gentle', 'low', 'solo', 'either', 'Set your phone out of reach, sit somewhere comfortable, and be quiet with God for five minutes.', 'You do not need any special words. Sitting quietly is one of the oldest ways people have made room for God.', 'Psalm 46:10', '“Be still, and know that I am God. I will be exalted among the nations. I will be exalted in the earth.”', 'What rose to the surface in the quiet?', 'God, help me be still with you.', 'roots', array['stillness', 'rest', 'quiet' ]::text[], array['ordinary_time', 'advent' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('one-quiet-cup', 'One Quiet Cup', 'silence', 15, 'gentle', 'low', 'solo', 'either', 'Drink one cup of coffee or tea today with no phone and no screen, just quiet.', 'An unhurried cup is a small way of practicing presence — to your own life, and to the God who is present in it.', 'Psalm 131:2', 'Surely I have stilled and quieted my soul, like a weaned child with his mother, like a weaned child is my soul within me.', 'What was it like to do one ordinary thing slowly?', 'God, meet me in the small, quiet moments.', 'roots', array['morning', 'rest', 'attention' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('a-quiet-commute', 'A Quiet Commute', 'silence', 15, 'gentle', 'low', 'solo', 'either', 'On your next drive, ride, or walk between places, leave the music and podcasts off and let the time be quiet.', 'The spaces between things are still part of the day God gave you. A quiet commute turns in-between time into open time.', 'Isaiah 30:15', 'For thus said the Lord Yahweh, the Holy One of Israel, “You will be saved in returning and rest. Your strength will be in quietness and in confidence.” You refused,', 'What did you notice once the noise was gone?', 'Lord, quiet me in the in-between places.', 'roots', array['commute', 'quiet', 'attention' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('listen-more-than-you-speak', 'Listen More Than You Speak', 'silence', 30, 'steady', 'medium', 'social', 'either', 'In one conversation today, choose to listen more than you speak, and let the other person finish without hurry.', 'Silence can be a gift we give. Listening well is a quiet form of love, and Scripture calls us to be quick to listen and slow to speak.', 'James 1:19', 'So, then, my beloved brothers, let every man be swift to hear, slow to speak, and slow to anger;', 'What did you learn by staying quiet a little longer?', 'Lord, teach me to listen the way you listen to me.', 'roots', array['listening', 'conversation', 'kindness' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('one-unplugged-hour', 'One Unplugged Hour', 'silence', 60, 'steady', 'low', 'solo', 'either', 'Set aside one hour today without your phone or screens, and let the quiet be unhurried.', 'Jesus drew his friends away to quiet places to rest. An hour without noise is not lost time; it is room to breathe.', 'Mark 6:31', 'He said to them, “You come apart into a deserted place, and rest awhile.” For there were many coming and going, and they had no leisure so much as to eat.', 'What did you want to reach for, and what happened when you let it be?', 'Lord, be enough for me in the quiet.', 'roots', array['unplugged', 'rest', 'sabbath' ]::text[], array['ordinary_time', 'lent' ]::text[], array['broadly_christian' ]::text[], array['discipline_sensitive' ]::text[], false, true, 'approved'),
  ('watch-the-evening-sky', 'Watch the Evening Sky', 'silence', 10, 'gentle', 'low', 'solo', 'either', 'As the day ends, sit outside or by a window and watch the sky in silence for ten minutes.', 'The sky has always drawn people toward wonder. Ending the day in quiet attention is a gentle way of remembering that your day rests in bigger hands than yours.', 'Psalm 8:3-4', 'When I consider your heavens, the work of your fingers, the moon and the stars, which you have ordained; what is man, that you think of him? What is the son of man, that you care for him?', 'What settled in you as you watched?', 'God, thank you for the wideness of this world and your care for me in it.', 'roots', array['evening', 'creation', 'wonder' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('read-one-psalm-slowly', 'Read One Psalm Slowly', 'scripture', 10, 'gentle', 'low', 'solo', 'either', 'Read Psalm 23 slowly, twice, and let one phrase rest with you.', 'Christians have returned to the psalms for thousands of years, especially when tired. Reading slowly turns words on a page into a place to rest.', 'Psalm 23:1-6', 'Yahweh is my shepherd: I shall lack nothing. He makes me lie down in green pastures. He leads me beside still waters. He restores my soul. He guides me in the paths of righteousness for his name’s sake. Even though I walk through the valley of the shadow of death, I will fear no evil, for you are with me. Your rod and your staff, they comfort me. You prepare a table before me in the presence of my enemies. You anoint my head with oil. My cup runs over. Surely goodness and loving kindness shall follow me all the days of my life, and I will dwell in Yahweh’s house forever.', 'Which phrase stayed with you, and what might it be saying to you today?', 'Lord, be my shepherd today.', 'branches', array['psalms', 'rest', 'reading' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('carry-a-verse-through-your-afternoon', 'Carry a Verse Through Your Afternoon', 'scripture', 240, 'steady', 'low', 'solo', 'either', 'Write one short verse where you will see it, and return to it whenever your afternoon pauses.', 'Scripture is not only for quiet corners; it can walk with you through ordinary hours. A verse carried is a verse slowly learned by heart.', 'Psalm 119:11', 'I have hidden your word in my heart, that I might not sin against you.', 'When you returned to the verse, what did it sound like in the middle of your day?', 'Lord, keep your word close to me today.', 'branches', array['memory', 'presence', 'work' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('read-the-good-samaritan', 'Read the Good Samaritan', 'scripture', 15, 'gentle', 'low', 'solo', 'either', 'Read the story of the Good Samaritan in Luke 10:25-37, a short story Jesus told about mercy, and notice who surprises you.', 'This is one of the most loved stories Jesus ever told. It quietly reshapes how we see the people we pass.', 'Luke 10:25-37', 'Behold, a certain lawyer stood up and tested him, saying, “Teacher, what shall I do to inherit eternal life?” He said to him, “What is written in the law? How do you read it?” He answered, “You shall love the Lord your God with all your heart, with all your soul, with all your strength, and with all your mind; and your neighbor as yourself.” He said to him, “You have answered correctly. Do this, and you will live.” But he, desiring to justify himself, asked Jesus, “Who is my neighbor?” Jesus answered, “A certain man was going down from Jerusalem to Jericho, and he fell among robbers, who both stripped him and beat him, and departed, leaving him half dead. By chance a certain priest was going down that way. When he saw him, he passed by on the other side. In the same way a Levite also, when he came to the place, and saw him, passed by on the other side. But a certain Samaritan, as he traveled, came where he was. When he saw him, he was moved with compassion, came to him, and bound up his wounds, pouring on oil and wine. He set him on his own animal, brought him to an inn, and took care of him. On the next day, when he departed, he took out two denarii, gave them to the host, and said to him, ‘Take care of him. Whatever you spend beyond that, I will repay you when I return.’ Now which of these three do you think seemed to be a neighbor to him who fell among the robbers?” He said, “He who showed mercy on him.” Then Jesus said to him, “Go and do likewise.”', 'Who in the story do you find yourself standing beside today?', 'Lord, teach me to be a neighbor.', 'branches', array['parables', 'mercy', 'neighbor' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('begin-a-gospel', 'Begin a Gospel', 'scripture', 15, 'gentle', 'low', 'solo', 'either', 'Read the first chapter of Mark, the shortest account of Jesus''s life, and simply notice what he does first.', 'Every journey with Jesus begins somewhere. Mark''s opening pages are a small, honest place to start, whoever you are.', 'Mark 1:1-45', 'The beginning of the Good News of Jesus Christ, the Son of God. As it is written in the prophets, “Behold, I send my messenger before your face, who will prepare your way before you: the voice of one crying in the wilderness, ‘Make ready the way of the Lord! Make his paths straight!’ ” John came baptizing in the wilderness and preaching the baptism of repentance for forgiveness of sins. All the country of Judea and all those of Jerusalem went out to him. They were baptized by him in the Jordan river, confessing their sins. John was clothed with camel’s hair and a leather belt around his waist. He ate locusts and wild honey. He preached, saying, “After me comes he who is mightier than I, the thong of whose sandals I am not worthy to stoop down and loosen. I baptized you in water, but he will baptize you in the Holy Spirit.” In those days, Jesus came from Nazareth of Galilee, and was baptized by John in the Jordan. Immediately coming up from the water, he saw the heavens parting, and the Spirit descending on him like a dove. A voice came out of the sky, “You are my beloved Son, in whom I am well pleased.” Immediately the Spirit drove him out into the wilderness. He was there in the wilderness forty days tempted by Satan. He was with the wild animals; and the angels were serving him. Now after John was taken into custody, Jesus came into Galilee, preaching the Good News of God’s Kingdom, and saying, “The time is fulfilled, and God’s Kingdom is at hand! Repent, and believe in the Good News.” Passing along by the sea of Galilee, he saw Simon and Andrew, the brother of Simon, casting a net into the sea, for they were fishermen. Jesus said to them, “Come after me, and I will make you into fishers for men.” Immediately they left their nets, and followed him. Going on a little further from there, he saw James the son of Zebedee, and John, his brother, who were also in the boat mending the nets. Immediately he called them, and they left their father, Zebedee, in the boat with the hired servants, and went after him. They went into Capernaum, and immediately on the Sabbath day he entered into the synagogue and taught. They were astonished at his teaching, for he taught them as having authority, and not as the scribes. Immediately there was in their synagogue a man with an unclean spirit, and he cried out, saying, “Ha! What do we have to do with you, Jesus, you Nazarene? Have you come to destroy us? I know you who you are: the Holy One of God!” Jesus rebuked him, saying, “Be quiet, and come out of him!” The unclean spirit, convulsing him and crying with a loud voice, came out of him. They were all amazed, so that they questioned among themselves, saying, “What is this? A new teaching? For with authority he commands even the unclean spirits, and they obey him!” The report of him went out immediately everywhere into all the region of Galilee and its surrounding area. Immediately, when they had come out of the synagogue, they came into the house of Simon and Andrew, with James and John. Now Simon’s wife’s mother lay sick with a fever, and immediately they told him about her. He came and took her by the hand, and raised her up. The fever left her immediately, and she served them. At evening, when the sun had set, they brought to him all who were sick, and those who were possessed by demons. All the city was gathered together at the door. He healed many who were sick with various diseases, and cast out many demons. He didn’t allow the demons to speak, because they knew him. Early in the morning, while it was still dark, he rose up and went out, and departed into a deserted place, and prayed there. Simon and those who were with him searched for him. They found him and told him, “Everyone is looking for you.” He said to them, “Let’s go elsewhere into the next towns, that I may preach there also, because I came out for this reason.” He went into their synagogues throughout all Galilee, preaching and casting out demons. A leper came to him, begging him, kneeling down to him, and saying to him, “If you want to, you can make me clean.” Being moved with compassion, he stretched out his hand, and touched him, and said to him, “I want to. Be made clean.” When he had said this, immediately the leprosy departed from him, and he was made clean. He strictly warned him, and immediately sent him out, and said to him, “See you say nothing to anybody, but go show yourself to the priest, and offer for your cleansing the things which Moses commanded, for a testimony to them.” But he went out, and began to proclaim it much, and to spread about the matter, so that Jesus could no more openly enter into a city, but was outside in desert places. People came to him from everywhere.', 'What surprised you about how the story begins?', 'Lord, meet me at the beginning.', 'branches', array['gospels', 'beginnings', 'reading' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('read-the-beatitudes-outside', 'Read the Beatitudes Outside', 'scripture', 30, 'steady', 'medium', 'solo', 'outdoor', 'Take your Bible or phone somewhere outdoors and read the Beatitudes in Matthew 5:1-12 slowly, under the open sky.', 'Jesus spoke these words on a hillside, in the open air. Hearing them outdoors can help them land as words for real life.', 'Matthew 5:1-12', 'Seeing the multitudes, he went up onto the mountain. When he had sat down, his disciples came to him. He opened his mouth and taught them, saying, “Blessed are the poor in spirit, for theirs is the Kingdom of Heaven. Blessed are those who mourn, for they shall be comforted. Blessed are the gentle, for they shall inherit the earth. Blessed are those who hunger and thirst after righteousness, for they shall be filled. Blessed are the merciful, for they shall obtain mercy. Blessed are the pure in heart, for they shall see God. Blessed are the peacemakers, for they shall be called children of God. Blessed are those who have been persecuted for righteousness’ sake, for theirs is the Kingdom of Heaven. “Blessed are you when people reproach you, persecute you, and say all kinds of evil against you falsely, for my sake. Rejoice, and be exceedingly glad, for great is your reward in heaven. For that is how they persecuted the prophets who were before you.', 'Which blessing sounded most unlike the world you move through?', 'Lord, bless the parts of me the world overlooks.', 'branches', array['gospels', 'outdoors', 'blessing' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('one-verse-before-your-phone', 'One Verse Before Your Phone', 'scripture', 5, 'gentle', 'low', 'solo', 'indoor', 'Before you scroll anything tonight, read one verse; Psalm 119:105 is a good place to begin.', 'What we read first often sets the tone for everything after. One verse is a small way to let God''s word have the first word.', 'Psalm 119:105', 'Your word is a lamp to my feet, and a light for my path.', 'How did the evening feel different when scripture came first?', 'Lord, let your word light my next step.', 'branches', array['evening', 'phone', 'habits' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], array['discipline_sensitive' ]::text[], false, true, 'approved'),
  ('look-back-on-your-day', 'Look Back on Your Day', 'reflection', 10, 'gentle', 'low', 'solo', 'either', 'Sit comfortably, look back over your day from morning to now, and notice one moment where something good happened.', 'Christians have long ended the day by looking back over it gently with God. Noticing is how gratitude begins.', 'Psalm 139:23-24', 'Search me, God, and know my heart. Try me, and know my thoughts. See if there is any wicked way in me, and lead me in the everlasting way.', 'Where in your day did you feel most alive, and where did you feel most drained?', 'Lord, thank you for walking through this day with me.', 'sunlight', array['evening', 'gratitude', 'noticing' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('name-what-you-are-carrying', 'Name What You Are Carrying', 'reflection', 10, 'gentle', 'low', 'solo', 'indoor', 'Write down, in a few honest words, the worries you are carrying today, and read the list once to God.', 'Naming a burden is often the first step toward handing it over. Scripture says we can cast our cares on God because he cares for us.', '1 Peter 5:7', 'casting all your worries on him, because he cares for you.', 'Now that they have names, do any of these worries feel different?', 'Lord, I hand you what I cannot hold.', 'sunlight', array['anxiety', 'honesty', 'rest' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['grief_sensitive' ]::text[], false, true, 'approved'),
  ('notice-where-kindness-found-you', 'Notice Where Kindness Found You', 'reflection', 10, 'gentle', 'low', 'solo', 'either', 'Think back over the past week and name one kindness someone showed you, however small.', 'Kindness received is grace made visible. Remembering it turns an ordinary week into evidence of care.', 'James 1:17', 'Every good gift and every perfect gift is from above, coming down from the Father of lights, with whom can be no variation, nor turning shadow.', 'What does that kindness tell you about how God might be caring for you?', 'Lord, thank you for the hands that carried kindness to me.', 'sunlight', array['gratitude', 'memory', 'kindness' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('a-walk-without-headphones', 'A Walk Without Headphones', 'reflection', 30, 'steady', 'medium', 'solo', 'outdoor', 'Take a short walk without headphones and let what you see and hear become your reflection.', 'Creation has its own quiet way of speaking. Walking unplugged makes room to notice what usually goes unheard.', 'Psalm 19:1', 'The heavens declare the glory of God. The expanse shows his handiwork.', 'What did you notice on your walk that you would normally miss?', 'Lord, open my eyes to what you have made.', 'sunlight', array['outdoors', 'noticing', 'quiet' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('release-one-old-hurt', 'Release One Old Hurt', 'reflection', 15, 'steady', 'medium', 'solo', 'either', 'In a quiet moment, name one old hurt to God and ask for his help to loosen your grip on it; nothing more is asked of you today.', 'Forgiveness is a journey that begins inside, long before anything else. Even the willingness to release is a step.', 'Ephesians 4:31-32', 'Let all bitterness, wrath, anger, outcry, and slander be put away from you, with all malice. And be kind to one another, tender hearted, forgiving each other, just as God also in Christ forgave you.', 'What might your heart feel like with a little less of this weight?', 'Lord, help me release what I have carried too long.', 'sunlight', array['forgiveness', 'healing', 'peace' ]::text[], array['ordinary_time', 'lent' ]::text[], array['broadly_christian' ]::text[], array['forgiveness_sensitive', 'relationship_sensitive' ]::text[], false, true, 'approved'),
  ('write-your-own-psalm', 'Write Your Own Psalm', 'reflection', 60, 'devoted', 'medium', 'solo', 'indoor', 'Set aside an unhurried hour to write an honest prayer in your own words — your joys, your questions, your hopes — the way the psalmists did.', 'The psalms show that God welcomes honest words, not polished ones. Writing your own is a way of pouring out your heart.', 'Psalm 62:8', 'Trust in him at all times, you people. Pour out your heart before him. God is a refuge for us.', 'What was it like to say to God exactly what you meant?', 'Lord, receive my honest words.', 'sunlight', array['writing', 'psalms', 'honesty' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('send-a-kind-word', 'Send a Kind Word', 'kindness', 5, 'gentle', 'low', 'solo', 'either', 'Send one honest, kind message to someone who comes to mind today.', 'A few true words can carry more weight than we know. Kindness often begins this small.', 'Ephesians 4:29', 'Let no corrupt speech proceed out of your mouth, but only what is good for building others up as the need may be, that it may give grace to those who hear.', 'Who came to mind first, and why do you think it was them?', 'God, give me words that are gentle and true.', 'leaves', array['encouragement', 'friendship', 'words' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('let-someone-go-first', 'Let Someone Go First', 'kindness', 5, 'gentle', 'medium', 'social', 'either', 'Once today, let someone go ahead of you — in line, in traffic, or through a door — and mean it.', 'Yielding a small place is a quiet way of honoring another person. It loosens the grip of hurry.', 'Philippians 2:3-4', 'doing nothing through rivalry or through conceit, but in humility, each counting others better than himself; each of you not just looking to his own things, but each of you also to the things of others.', 'What did it feel like to slow down and make room for someone?', 'God, teach me to make room for others.', 'leaves', array['patience', 'humility', 'everyday' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('thank-someone-who-serves-you', 'Thank Someone Who Serves You', 'kindness', 5, 'gentle', 'medium', 'social', 'either', 'Thank someone who serves you today — a cashier, a driver, a coworker — slowly enough that they know you mean it.', 'Gratitude turns a transaction into a meeting between two people. Kindness notices the ones who are easy to overlook.', 'Colossians 3:12', 'Put on therefore, as God’s chosen ones, holy and beloved, a heart of compassion, kindness, lowliness, humility, and perseverance;', 'Whom do you pass most days without really seeing?', 'Lord, open my eyes to the people I usually hurry past.', 'leaves', array['gratitude', 'strangers', 'everyday' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('speak-gently-to-yourself', 'Speak Gently to Yourself', 'kindness', 10, 'gentle', 'low', 'solo', 'either', 'When you catch a harsh thought about yourself today, answer it the way you would answer a tired friend.', 'God is gentler with us than we are with ourselves. Practicing that gentleness is not indulgence; it is trust.', 'Psalm 103:13-14', 'Like a father has compassion on his children, so Yahweh has compassion on those who fear him. For he knows how we are made. He remembers that we are dust.', 'What would change if you believed God looks at you with compassion?', 'God, help me receive the same mercy I hope to give.', 'leaves', array['self-compassion', 'rest', 'mercy' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('write-an-unhurried-note', 'Write an Unhurried Note', 'kindness', 15, 'steady', 'medium', 'solo', 'indoor', 'Handwrite a short note of thanks or encouragement and leave it where the right person will find it.', 'A written word lasts longer than a spoken one. It says: I stopped, and I thought of you.', 'Hebrews 10:24', 'Let’s consider how to provoke one another to love and good works,', 'What made you choose the person you wrote to?', 'Lord, let my words build someone up today.', 'leaves', array['encouragement', 'writing', 'gratitude' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('carry-kindness-through-the-afternoon', 'Carry Kindness Through the Afternoon', 'kindness', 240, 'steady', 'medium', 'either', 'either', 'Carry one quiet intention through your afternoon: when small exchanges come — a checkout line, a hallway, a reply — meet them with kindness, without announcing it.', 'Kindness practiced in secret shapes us more than kindness performed. The afternoon offers dozens of small doors.', 'Micah 6:8', 'He has shown you, O man, what is good. What does Yahweh require of you, but to act justly, to love mercy, and to walk humbly with your God?', 'Where did kindness come easily today, and where did it cost you something?', 'Lord, keep me kind when no one is watching.', 'leaves', array['intention', 'mercy', 'everyday' ]::text[], array['ordinary_time', 'lent' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('pray-for-your-neighbors', 'Pray for Your Neighbors', 'community', 10, 'gentle', 'low', 'solo', 'indoor', 'From wherever you are sitting, pray for your neighbors — house by house, door by door, as far as you know them.', 'Scripture asks God''s people to seek the good of the place they live. Prayer is how that seeking begins.', 'Jeremiah 29:7', 'Seek the peace of the city where I have caused you to be carried away captive, and pray to Yahweh for it; for in its peace you will have peace.”', 'Which neighbor stayed on your mind after you finished?', 'Lord, bless the people who live near me, whether or not I know their names.', 'roots', array['prayer', 'neighbors', 'home' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('learn-a-neighbors-name', 'Learn a Neighbor''s Name', 'community', 5, 'gentle', 'medium', 'social', 'outdoor', 'Greet one neighbor today and learn their name — or use the name you already know, warmly.', 'Loving a neighbor starts with knowing one. A name is a small door into care.', 'Mark 12:31', 'The second is like this, ‘You shall love your neighbor as yourself.’ There is no other commandment greater than these.”', 'How did it change the moment when you used their name?', 'God, help me see the people who live beside me.', 'leaves', array['neighbors', 'hospitality', 'courage' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('check-in-on-an-old-friend', 'Check In on an Old Friend', 'community', 10, 'steady', 'low', 'solo', 'either', 'Send a simple message to a friend you have quietly drifted from — no agenda, just to say you thought of them.', 'Friendships fade quietly, and they can be rekindled quietly too. Bearing one another''s burdens begins with showing up.', 'Galatians 6:2', 'Bear one another’s burdens, and so fulfill the law of Christ.', 'What do you miss about this friendship?', 'Lord, thank you for the people who have walked part of the road with me.', 'leaves', array['friendship', 'connection', 'faithfulness' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['relationship_sensitive' ]::text[], false, true, 'approved'),
  ('share-a-meal-with-someone', 'Share a Meal with Someone', 'community', 60, 'devoted', 'high', 'social', 'either', 'Invite someone to share a simple meal or a cup of coffee with you, today if you can. Your own table, and whatever you already have, is enough.', 'The early church grew around ordinary tables. Something in us opens when we eat together.', 'Acts 2:46', 'Day by day, continuing steadfastly with one accord in the temple, and breaking bread at home, they took their food with gladness and singleness of heart,', 'What came up in the conversation that would not have come up in passing?', 'Lord, make my table a welcoming place.', 'fruit', array['hospitality', 'meals', 'fellowship' ]::text[], array['ordinary_time', 'easter' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('ask-an-elder-for-a-story', 'Ask an Elder for a Story', 'community', 30, 'steady', 'medium', 'social', 'either', 'Call or sit with an older person you trust and ask them to tell you a story from their life.', 'Listening honors a life. The church has always believed the old and the young need each other.', 'Job 12:12', 'With aged men is wisdom, in length of days understanding.', 'What did their story teach you that you could not have learned alone?', 'Lord, thank you for the long faithfulness of those who walked before me.', 'leaves', array['listening', 'elders', 'stories' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('bless-the-room', 'Bless the Room', 'community', 10, 'gentle', 'low', 'solo', 'either', 'Wherever people gather around you today, silently ask God to bless each person you can see.', 'A hidden blessing changes the one who prays it. Strangers become neighbors in the quiet of the heart.', 'Numbers 6:24-26', '‘Yahweh bless you, and keep you. Yahweh make his face to shine on you, and be gracious to you. Yahweh lift up his face toward you, and give you peace.’', 'How did the room feel different once you had prayed for the people in it?', 'God, bless each person near me today, in the ways they need most.', 'roots', array['prayer', 'strangers', 'presence' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('carry-someones-load', 'Carry Someone''s Load', 'service', 10, 'gentle', 'medium', 'solo', 'indoor', 'Quietly take on one small task today that usually belongs to someone else, like the dishes, the trash, or tidying a shared space.', 'When we carry a small piece of someone else''s day, we practice the love Christ asks of us. It is ordinary work, and that is exactly where love lives.', 'Galatians 6:2', 'Bear one another’s burdens, and so fulfill the law of Christ.', 'What did you notice about the person whose load you carried?', 'God, teach me to see the small burdens I can carry for others.', 'fruit', array['home', 'humility', 'helping' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('serve-without-being-seen', 'Serve Without Being Seen', 'service', 15, 'steady', 'medium', 'solo', 'either', 'Do one helpful thing today that no one will know you did, like tidying a shared space, refilling what has run out, or picking up stray litter, and keep it between you and God.', 'Hidden service frees us from performing. Work done quietly, as for the Lord, shapes the heart more than work done for applause.', 'Colossians 3:23', 'And whatever you do, work heartily, as for the Lord, and not for men,', 'How did it feel to help without anyone knowing?', 'Lord, let me be content to serve where only you can see.', 'fruit', array['humility', 'quiet', 'hidden service' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('make-way-for-a-stranger', 'Make Way for a Stranger', 'service', 5, 'gentle', 'low', 'solo', 'outdoor', 'While you are out today, offer one small courtesy to a stranger, like returning a cart, holding a door, or letting someone go ahead of you.', 'Jesus taught that small kindnesses to ordinary people are kindnesses to him. A five-second courtesy can be a quiet act of faith.', 'Matthew 25:40', '“The King will answer them, ‘Most certainly I tell you, because you did it to one of the least of these my brothers, you did it to me.’', 'Who crossed your path today that you might otherwise have overlooked?', 'God, help me notice the people in front of me.', 'fruit', array['strangers', 'errands', 'courtesy' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('lend-a-hand-at-work', 'Lend a Hand at Work', 'service', 15, 'steady', 'medium', 'social', 'indoor', 'Notice one task a coworker or classmate is carrying today, and offer fifteen minutes of real help with it.', 'Faith is not only for quiet mornings; it walks into workplaces too. Looking to the interests of others turns an ordinary Tuesday into a place of grace.', 'Philippians 2:4', 'each of you not just looking to his own things, but each of you also to the things of others.', 'What changed between you and the person you helped?', 'Lord, make my work a way of loving the people around me.', 'fruit', array['work', 'helping', 'colleagues' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('one-hour-given', 'One Hour, Given', 'service', 60, 'devoted', 'high', 'either', 'either', 'Set aside one unhurried hour today to serve someone, perhaps helping a neighbor, preparing a meal for a tired friend, or caring for a shared space.', 'Jesus described his own life as one of service, not of being served. Giving a whole hour, without rushing, lets us walk a small stretch of that same road.', 'Mark 10:45', 'For the Son of Man also came not to be served, but to serve, and to give his life as a ransom for many.”', 'Where did you sense God during the hour you gave away?', 'Lord, let this hour belong to someone other than me.', 'fruit', array['neighbors', 'time', 'helping' ]::text[], array['ordinary_time', 'lent' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('ask-what-someone-needs', 'Ask What Someone Needs', 'service', 5, 'gentle', 'low', 'social', 'indoor', 'Send one honest message to someone in your life asking what you could do to make their week a little lighter.', 'Service begins with asking, not assuming. Even from the couch, on a tired day, one question can open a door for love.', 'Galatians 5:13', 'For you, brothers, were called for freedom. Only don’t use your freedom for gain to the flesh, but through love be servants to one another.', 'What did it feel like to ask instead of assuming you already knew?', 'God, give me the humility to ask and the willingness to follow through.', 'fruit', array['listening', 'friends', 'low energy' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('set-something-aside-to-give', 'Set Something Aside to Give', 'generosity', 10, 'gentle', 'medium', 'solo', 'indoor', 'Choose one thing you own that is in good condition, and set it aside today to pass along to someone who could use it.', 'Loosening our grip on one possession is a small rehearsal of trust. Giving reminds us that what we hold was first given to us.', 'Acts 20:35', 'In all things I gave you an example, that so laboring you ought to help the weak, and to remember the words of the Lord Jesus, that he himself said, ‘It is more blessed to give than to receive.’”', 'What was it like to let go of something you own?', 'Lord, loosen my hands so that good things can pass through them.', 'fruit', array['giving', 'possessions', 'simplicity' ]::text[], array['ordinary_time', 'advent' ]::text[], array['broadly_christian' ]::text[], array['money_sensitive' ]::text[], false, true, 'approved'),
  ('a-quiet-gift', 'A Quiet Gift', 'generosity', 5, 'gentle', 'low', 'solo', 'either', 'If it is within your means, give a small gift today to a cause or person you trust, and tell no one about it.', 'Jesus invited his followers to give in secret, where generosity stays honest. The size of the gift matters far less than the quiet of the heart behind it.', 'Matthew 6:3-4', 'But when you do merciful deeds, don’t let your left hand know what your right hand does, so that your merciful deeds may be in secret, then your Father who sees in secret will reward you openly.', 'What did giving in secret free you from?', 'God, let my giving be simple, quiet, and glad.', 'fruit', array['giving', 'secrecy', 'trust' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['money_sensitive' ]::text[], false, true, 'approved'),
  ('give-your-full-attention', 'Give Your Full Attention', 'generosity', 15, 'gentle', 'low', 'social', 'either', 'Give one person your whole attention today for fifteen minutes, with your phone out of reach and no hurry to speak.', 'Attention may be the most generous thing we can give. Listening well is a way of saying: you matter, and I am not in a rush.', 'James 1:19', 'So, then, my beloved brothers, let every man be swift to hear, slow to speak, and slow to anger;', 'What did you hear that you might have missed on an ordinary day?', 'God, quiet my hurry so I can truly listen.', 'fruit', array['listening', 'presence', 'attention' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('ten-minutes-for-someone-lonely', 'Ten Minutes for Someone Lonely', 'generosity', 10, 'gentle', 'low', 'social', 'indoor', 'Call or message someone who may be lonely today, and give them ten unhurried minutes of your company.', 'Time is a gift we rarely think to give. A short call can remind someone they are held in affection, and remind us that love is often this simple.', 'Romans 12:10', 'In love of the brothers be tenderly affectionate to one another; in honor preferring one another;', 'How did the conversation change the shape of your day?', 'Lord, bring to mind the person who needs company today.', 'fruit', array['loneliness', 'time', 'connection' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('share-what-you-have', 'Share What You Have', 'generosity', 15, 'gentle', 'medium', 'social', 'either', 'Share something you already have today, like a meal, a cup of coffee, a book, or the extra portion you made, with someone nearby.', 'Scripture calls sharing a kind of offering. We do not need more in order to be generous; we only need open hands with what is already ours.', 'Hebrews 13:16', 'But don’t forget to be doing good and sharing, for with such sacrifices God is well pleased.', 'What do you already have that seems meant to be shared?', 'God, show me what in my hands is meant for someone else.', 'fruit', array['sharing', 'food', 'hospitality' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('open-hands-through-the-afternoon', 'Open Hands Through the Afternoon', 'generosity', 240, 'steady', 'low', 'either', 'either', 'Begin your afternoon with a short prayer of open hands, then watch for one small chance to give a little time, attention, or help before the evening comes.', 'Generosity is a posture before it is an act. Holding the day loosely, we begin to give the way God loves: freely and gladly.', '2 Corinthians 9:7', 'Let each man give according as he has determined in his heart, not grudgingly or under compulsion, for God loves a cheerful giver.', 'Where did an open hand find something to do this afternoon?', 'Lord, keep my hands open through the ordinary hours of this day.', 'fruit', array['intention', 'awareness', 'giving' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('name-the-weight', 'Name the Weight', 'forgiveness', 10, 'gentle', 'low', 'solo', 'either', 'Sit somewhere quiet and name, honestly and without hurry, one hurt you are still carrying.', 'We cannot release what we have not named. Bringing a hurt into the light before God is the quiet beginning of forgiveness.', 'Psalm 55:22', 'Cast your burden on Yahweh and he will sustain you. He will never allow the righteous to be moved.', 'What did it feel like to say the hurt out loud, even just to God?', 'Lord, I hand you this weight; help me carry it no longer alone.', 'roots', array['prayer', 'release', 'honesty' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['forgiveness_sensitive' ]::text[], false, true, 'approved'),
  ('write-an-unsent-letter', 'Write an Unsent Letter', 'forgiveness', 30, 'steady', 'medium', 'solo', 'indoor', 'Write a letter you will never send to someone who hurt you, saying everything you need to say, then set it aside or tear it up.', 'The page can hold what the heart has carried too long. Forgiveness often begins as private, honest work between you and God.', 'Ephesians 4:31-32', 'Let all bitterness, wrath, anger, outcry, and slander be put away from you, with all malice. And be kind to one another, tender hearted, forgiving each other, just as God also in Christ forgave you.', 'What surprised you as the words came out?', 'God of mercy, receive what I have written and begin to soften what is hard in me.', 'sunlight', array['writing', 'release', 'bitterness' ]::text[], array['ordinary_time', 'lent' ]::text[], array['broadly_christian' ]::text[], array['forgiveness_sensitive', 'relationship_sensitive' ]::text[], false, true, 'approved'),
  ('pray-for-someone-hard-to-love-2', 'Pray for Someone Hard to Love', 'forgiveness', 5, 'gentle', 'low', 'solo', 'either', 'Pray one honest sentence today for a person you find hard to love.', 'Jesus asked his friends to pray for the people who hurt them. Prayer does not excuse the wrong; it loosens its grip on us.', 'Matthew 5:44', 'But I tell you, love your enemies, bless those who curse you, do good to those who hate you, and pray for those who mistreat you and persecute you,', 'What was it like to bring that name into prayer?', 'Lord, bless them, and free my heart from what I hold against them.', 'roots', array['prayer', 'mercy', 'release' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['forgiveness_sensitive', 'relationship_sensitive' ]::text[], false, true, 'approved'),
  ('open-your-hands', 'Open Your Hands', 'forgiveness', 10, 'gentle', 'low', 'solo', 'either', 'Sit with your fists gently closed, name an old hurt, then slowly open your hands as a small sign of letting go.', 'Sometimes the body can pray what words cannot. Opening your hands is a quiet way of asking God to take what you cannot keep carrying.', 'Colossians 3:13', 'bearing with one another, and forgiving each other, if any man has a complaint against any; even as Christ forgave you, so you also do.', 'What are you still holding, and what would it mean to loosen your grip a little?', 'God, I open my hands; take what I have been holding too tightly.', 'roots', array['prayer', 'body', 'release' ]::text[], array['ordinary_time', 'lent' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], array['forgiveness_sensitive' ]::text[], false, true, 'approved'),
  ('forgive-yourself-one-thing', 'Forgive Yourself One Thing', 'forgiveness', 15, 'gentle', 'low', 'solo', 'either', 'Name one thing you still hold against yourself. Then read Psalm 103:12 slowly, and hear it spoken over that very thing.', 'Many of us extend to others a mercy we refuse ourselves. Receiving forgiveness is part of learning to give it.', 'Psalm 103:12', 'As far as the east is from the west, so far has he removed our transgressions from us.', 'Why is it hard to let yourself be forgiven?', 'Lord, you have let this go; help me let it go too.', 'sunlight', array['mercy', 'self-compassion', 'grace' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['forgiveness_sensitive' ]::text[], false, true, 'approved'),
  ('walk-and-release', 'Walk and Release', 'forgiveness', 30, 'steady', 'medium', 'solo', 'outdoor', 'Take a slow walk, and with each stretch of the way, quietly ask God to loosen one old hurt you have carried.', 'Pilgrims have always prayed with their feet. A walk gives grief and grievance somewhere to go.', 'Psalm 147:3', 'He heals the broken in heart, and binds up their wounds.', 'Did the hurt feel any lighter by the end of the walk, even slightly?', 'Healer of hearts, walk with me and teach me how to let this go.', 'roots', array['walking', 'release', 'healing' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['forgiveness_sensitive', 'grief_sensitive' ]::text[], false, true, 'approved'),
  ('let-someone-go-first-2', 'Let Someone Go First', 'patience', 15, 'gentle', 'medium', 'social', 'either', 'The next time you are in a line or in traffic today, let someone go ahead of you without hurry or announcement.', 'Patience becomes real in small surrenders. Yielding a place is a quiet way of honoring another person.', 'Philippians 2:3', 'doing nothing through rivalry or through conceit, but in humility, each counting others better than himself;', 'What rose up in you when you chose to wait?', 'God, teach me to make room for others with a glad heart.', 'leaves', array['yielding', 'errands', 'humility' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('wait-without-your-phone', 'Wait Without Your Phone', 'patience', 10, 'gentle', 'low', 'solo', 'either', 'The next time you find yourself waiting today, leave your phone in your pocket and let the waiting be quiet.', 'Waiting is one of the oldest schools of the soul. Small empty moments can become small open ones.', 'Psalm 27:14', 'Wait for Yahweh. Be strong, and let your heart take courage. Yes, wait for Yahweh.', 'What did you notice in the quiet that you usually miss?', 'God, meet me in the waiting.', 'leaves', array['waiting', 'stillness', 'attention' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], array['discipline_sensitive' ]::text[], false, true, 'approved'),
  ('listen-without-interrupting', 'Listen Without Interrupting', 'patience', 15, 'gentle', 'medium', 'social', 'either', 'In one conversation today, let the other person finish everything they want to say before you speak.', 'Listening well is patience with a face. It tells another person their words are worth your time.', 'James 1:19', 'So, then, my beloved brothers, let every man be swift to hear, slow to speak, and slow to anger;', 'What did you hear that you might have missed?', 'Lord, slow my tongue and open my ears.', 'leaves', array['listening', 'conversation', 'presence' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('carry-patience-through-the-afternoon', 'Carry Patience Through the Afternoon', 'patience', 240, 'steady', 'low', 'either', 'either', 'Choose the words ''slow to anger, rich in mercy'' and return to them gently each time you have to wait this afternoon.', 'Patience grows less by effort than by remembering who God is. A phrase carried through ordinary hours can slowly change their weather.', 'Psalm 103:8', 'Yahweh is merciful and gracious, slow to anger, and abundant in loving kindness.', 'When was it hardest to return to the words, and what helped you come back?', 'Lord, slow to anger and rich in mercy, shape my afternoon.', 'leaves', array['waiting', 'daily-life', 'mercy' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('be-patient-with-yourself', 'Be Patient With Yourself', 'patience', 5, 'gentle', 'low', 'solo', 'either', 'Wherever you are right now, take three slow breaths, then say one kind and true sentence to yourself, as gently as God speaks to the weary.', 'God''s compassion covers the tired and the unfinished. Being gentle with yourself is not weakness; it is trust.', 'Psalm 103:13-14', 'Like a father has compassion on his children, so Yahweh has compassion on those who fear him. For he knows how we are made. He remembers that we are dust.', 'Where have you been hardest on yourself lately?', 'God, you know what I am made of; be gentle with me, and help me be gentle too.', 'sunlight', array['rest', 'self-compassion', 'gentleness' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('one-unhurried-hour', 'One Unhurried Hour', 'patience', 60, 'steady', 'medium', 'solo', 'either', 'Choose one hour today and move through it at an unhurried pace, doing whatever it holds without rushing.', 'Hurry is a habit, and so is peace. One slow hour teaches the body what the heart already suspects: most things can wait.', 'Ecclesiastes 3:1', 'For everything there is a season, and a time for every purpose under heaven:', 'What felt different when you stopped rushing?', 'Lord of all seasons, teach me an unhurried heart.', 'leaves', array['slowness', 'rest', 'daily-life' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('three-small-thanks', 'Three Small Thanks', 'gratitude', 5, 'gentle', 'low', 'solo', 'either', 'Before the day ends, name three small things you are thankful for.', 'Gratitude begins with noticing. Naming small gifts is an old and simple way of returning to God.', '1 Thessalonians 5:18', 'In everything give thanks, for this is the will of God in Christ Jesus toward you.', 'Which of the three surprised you?', 'Thank you, God, for the small gifts I almost missed.', 'flowers', array['noticing', 'thankfulness', 'evening' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('thank-someone-who-helped-you', 'Thank Someone Who Helped You', 'gratitude', 10, 'gentle', 'medium', 'social', 'either', 'Send a short, honest thank-you to someone — a friend, a relative, a coworker — whose help you never fully acknowledged.', 'Gratitude grows when it is spoken. A simple thank-you honors the way God cares for us through other people.', 'Philippians 1:3', 'I thank my God whenever I remember you,', 'What changed in you when you put your thanks into words?', 'Lord, thank you for the people you have placed in my life.', 'flowers', array['thankfulness', 'relationships', 'encouragement' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('grace-before-one-meal', 'Grace Before One Meal', 'gratitude', 5, 'gentle', 'low', 'either', 'indoor', 'Before one meal today, pause and quietly give thanks for the food in front of you.', 'Pausing before we eat is one of the oldest Christian habits. It turns an ordinary meal into a small act of gratitude.', '1 Timothy 4:4-5', 'For every creature of God is good, and nothing is to be rejected, if it is received with thanksgiving. For it is sanctified through the word of God and prayer.', 'How did the meal feel different after you paused?', 'Thank you, God, for this food and for every hand that brought it to me.', 'flowers', array['meals', 'thankfulness', 'home' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('carry-gratitude-through-the-afternoon', 'Carry Gratitude Through the Afternoon', 'gratitude', 240, 'steady', 'low', 'solo', 'either', 'Carry one quiet intention through your afternoon: whenever a small gift comes — warm light, a kind word, a task finished — pause and thank God for it in silence.', 'Gratitude is not only a moment but a way of walking through the day. Noticing is how thankfulness becomes a habit of the heart.', 'Psalm 118:24', 'This is the day that Yahweh has made. We will rejoice and be glad in it!', 'What did you notice this afternoon that you would usually walk past?', 'God, open my eyes to the gifts in this day.', 'flowers', array['noticing', 'presence', 'daily-life' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('a-walk-of-noticing', 'A Walk of Noticing', 'gratitude', 30, 'steady', 'medium', 'solo', 'outdoor', 'Take a slow walk and quietly thank God for what you see along the way.', 'Creation has always led people to gratitude. A slow walk gives thankfulness room to breathe.', 'Psalm 19:1', 'The heavens declare the glory of God. The expanse shows his handiwork.', 'What did you see today that felt like a gift?', 'Thank you, Lord, for the world you have made.', 'flowers', array['creation', 'walking', 'noticing' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('thanks-after-a-hard-season', 'Thanks After a Hard Season', 'gratitude', 15, 'steady', 'low', 'solo', 'indoor', 'Write a few honest lines about a hard season, and gently name one small mercy that carried you through it. If no mercy comes to mind yet, write that too; honesty is its own prayer.', 'Gratitude does not deny sorrow; it looks for the mercy inside it. This is slow work, and it cannot be rushed.', 'Lamentations 3:22-23', 'It is because of Yahweh’s loving kindnesses that we are not consumed, because his compassion doesn’t fail. They are new every morning. Great is your faithfulness.', 'Looking back, what do you see now that you could not see at the time?', 'Lord, thank you for staying near me in the hard days.', 'sunlight', array['healing', 'reflection', 'mercy' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['grief_sensitive' ]::text[], false, true, 'approved'),
  ('sing-one-song', 'Sing One Song', 'worship', 10, 'gentle', 'low', 'solo', 'indoor', 'Play or quietly sing one song that turns your heart toward God, and give it your whole attention from beginning to end.', 'Music is one of the oldest ways people have reached toward God. One song, honestly attended to, is enough.', 'Psalm 95:1', 'Oh come, let’s sing to Yahweh. Let’s shout aloud to the rock of our salvation!', 'What line stayed with you after the song ended?', 'God, receive this song as my thanks and my praise.', 'flowers', array['music', 'praise', 'quiet' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('pray-a-psalm-of-praise', 'Pray a Psalm of Praise', 'worship', 10, 'gentle', 'low', 'solo', 'indoor', 'Read Psalm 100 slowly, and let its words become your own prayer.', 'The psalms have carried the church''s worship for thousands of years. Praying one joins your voice to that long song.', 'Psalm 100:1-2', 'Shout for joy to Yahweh, all you lands! Serve Yahweh with gladness. Come before his presence with singing.', 'Which word of the psalm felt most like your own?', 'Lord, teach me to praise you with words older than my own.', 'branches', array['psalms', 'scripture', 'praise' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('worship-in-the-ordinary', 'Worship in the Ordinary', 'worship', 15, 'gentle', 'medium', 'solo', 'indoor', 'Choose one ordinary task today — dishes, a letter, a chore — and do it slowly, as a quiet offering to God.', 'Worship is not confined to Sunday mornings. Ordinary work, done with love and attention, can be offered to God.', 'Colossians 3:17', 'Whatever you do, in word or in deed, do all in the name of the Lord Jesus, giving thanks to God the Father, through him.', 'How did the task change when you offered it to God?', 'Lord, let my ordinary work be a gift to you.', 'flowers', array['work', 'daily-life', 'offering' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('five-minutes-of-praise', 'Five Minutes of Praise', 'worship', 5, 'gentle', 'low', 'solo', 'either', 'Spend five minutes telling God who he is, without asking for anything.', 'Praise sets our requests aside for a moment. It rests the heart on God rather than on our needs.', 'Psalm 145:3', 'Great is Yahweh, and greatly to be praised! His greatness is unsearchable.', 'What was it like to pray without asking?', 'God, you are good, and I simply want to say so.', 'flowers', array['praise', 'prayer', 'quiet' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('step-outside-and-look-up', 'Step Outside and Look Up', 'worship', 10, 'gentle', 'medium', 'solo', 'outdoor', 'Step outside, look up at the sky for a few minutes, and let whatever wonder you feel turn quietly toward God.', 'You do not need special words to worship. Wonder, honestly felt, is already a beginning.', 'Psalm 8:3-4', 'When I consider your heavens, the work of your fingers, the moon and the stars, which you have ordained; what is man, that you think of him? What is the son of man, that you care for him?', 'What did the sky stir in you?', 'God, the world you made is beyond me, and I am glad.', 'flowers', array['creation', 'wonder', 'outdoors' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('an-hour-set-apart', 'An Hour Set Apart', 'worship', 60, 'devoted', 'medium', 'solo', 'indoor', 'Set apart one quiet hour today for God — some scripture, some music, some silence, and no agenda.', 'Unhurried time is its own form of praise. An hour given freely says, more than words, that God is worth our attention.', 'Psalm 27:4', 'One thing I have asked of Yahweh, that I will seek after: that I may dwell in Yahweh’s house all the days of my life, to see Yahweh’s beauty, and to inquire in his temple.', 'What rose in you when the hour had no agenda?', 'Lord, here is my hour; I want nothing from it but you.', 'flowers', array['rest', 'presence', 'quiet' ]::text[], array['ordinary_time', 'lent' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('thank-someone-in-your-family', 'Thank Someone in Your Family', 'family', 5, 'gentle', 'low', 'either', 'either', 'Tell one family member, in person or by message, one specific thing you are thankful for about them.', 'Gratitude kept inside blesses no one. Spoken plainly, it becomes a small gift that costs nothing and is rarely forgotten.', 'Philippians 1:3', 'I thank my God whenever I remember you,', 'What made you choose this person today?', 'Lord, thank you for the people you have placed in my life.', 'fruit', array['gratitude', 'family', 'encouragement' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], array['relationship_sensitive' ]::text[], false, true, 'approved'),
  ('listen-without-fixing', 'Listen Without Fixing', 'family', 15, 'steady', 'medium', 'social', 'either', 'Give a family member fifteen unhurried minutes today, listening without advice, correction, or fixing.', 'Being truly heard is rare, and family often receives the least of our attention. Listening is a form of love that asks nothing in return.', 'James 1:19', 'So, then, my beloved brothers, let every man be swift to hear, slow to speak, and slow to anger;', 'What did you hear because you stayed quiet?', 'Lord, make me quick to listen and slow to speak.', 'leaves', array['listening', 'family', 'patience' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['relationship_sensitive' ]::text[], false, true, 'approved'),
  ('pray-for-your-family-by-name', 'Pray for Your Family by Name', 'family', 10, 'gentle', 'low', 'solo', 'either', 'Sit somewhere quiet and pray for each member of your family by name, near or far, one at a time.', 'Praying for someone by name turns a general love into a particular one. It is a way of carrying your family even when they are not near.', 'Ephesians 1:16', 'don’t cease to give thanks for you, making mention of you in my prayers,', 'Which name stayed with you after you finished?', 'Father, be near to each one I have named.', 'roots', array['prayer', 'family', 'intercession' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['relationship_sensitive' ]::text[], false, true, 'approved'),
  ('do-one-chore-unasked', 'Do One Chore Unasked', 'family', 15, 'gentle', 'medium', 'solo', 'indoor', 'Quietly take care of one small task at home that usually belongs to someone else, without announcing it.', 'Hidden service is love with no audience. Jesus washed feet; we can wash dishes.', 'Galatians 5:13', 'For you, brothers, were called for freedom. Only don’t use your freedom for gain to the flesh, but through love be servants to one another.', 'How did it feel to serve without being seen?', 'Lord, teach me to serve gladly in small things.', 'fruit', array['service', 'home', 'humility' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('ask-about-the-old-days', 'Ask About the Old Days', 'family', 30, 'steady', 'medium', 'social', 'either', 'Call or sit with an older family member today and ask them to tell you about a time they remember well.', 'Every family carries stories that fade unless someone asks. Listening to our elders is an old and honored way of loving them.', 'Deuteronomy 32:7', 'Remember the days of old. Consider the years of many generations. Ask your father, and he will show you; your elders, and they will tell you.', 'What did you learn that you did not know before?', 'Lord, thank you for the lives that came before mine.', 'fruit', array['elders', 'listening', 'family' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['relationship_sensitive', 'grief_sensitive' ]::text[], false, true, 'approved'),
  ('an-afternoon-of-gentle-words', 'An Afternoon of Gentle Words', 'family', 240, 'devoted', 'low', 'either', 'either', 'Carry one quiet intention through your afternoon: to speak gently at home, and to simply begin again whenever you forget.', 'Homes are built or worn down by ordinary words. Gentleness practiced for a single afternoon is a real gift to the people who live with us.', 'Proverbs 15:1', 'A gentle answer turns away wrath, but a harsh word stirs up anger.', 'When was it hardest to answer gently today?', 'Lord, let my words today be gentle ones.', 'leaves', array['gentleness', 'speech', 'home' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['relationship_sensitive' ]::text[], false, true, 'approved'),
  ('one-hour-without-your-phone', 'One Hour Without Your Phone', 'discipline', 60, 'steady', 'low', 'solo', 'either', 'Set your phone in another room for one hour and let the quiet be what it is.', 'Stepping away from the phone is a small fast, a way of making room. Even one hour of quiet can remind us that we are held.', 'Psalm 46:10', '“Be still, and know that I am God. I will be exalted among the nations. I will be exalted in the earth.”', 'What rose up in the quiet once the noise was gone?', 'God, help me be still and know that you are here.', 'roots', array['silence', 'rest', 'phone' ]::text[], array['ordinary_time', 'lent' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], array['discipline_sensitive' ]::text[], false, true, 'approved'),
  ('a-psalm-before-your-phone', 'A Psalm Before Your Phone', 'discipline', 5, 'gentle', 'low', 'solo', 'either', 'Before the next time you pick up your phone to scroll, read Psalm 23 slowly, just once.', 'What we read first shapes how we see everything after. A psalm is a small lamp to carry into the rest of the day.', 'Psalm 119:105', 'Your word is a lamp to my feet, and a light for my path.', 'What line stayed with you?', 'Lord, let your word be the first voice I listen to.', 'branches', array['scripture', 'psalms', 'habits' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('one-hour-without-complaint', 'One Hour Without Complaint', 'discipline', 60, 'devoted', 'medium', 'either', 'either', 'For one hour, each time a complaint rises, let it pass and quietly name one true thing you are thankful for.', 'Complaint narrows the heart; gratitude widens it. Christians have practiced this trade for centuries, one hour at a time.', 'Philippians 2:14', 'Do all things without complaining and arguing,', 'What did you notice about your own habits of speech?', 'Lord, turn my grumbling into gratitude.', 'flowers', array['gratitude', 'speech', 'self-control' ]::text[], array['ordinary_time', 'lent' ]::text[], array['broadly_christian' ]::text[], array['discipline_sensitive' ]::text[], false, true, 'approved'),
  ('five-minutes-of-stillness', 'Five Minutes of Stillness', 'discipline', 5, 'gentle', 'low', 'solo', 'either', 'Sit still for five minutes today with nothing in your hands, and simply rest in God''s presence.', 'Stillness is not doing nothing. It is practicing trust, letting God hold the world for five minutes without our help.', 'Psalm 62:1', 'My soul rests in God alone. My salvation is from him.', 'What was it like to stop, even briefly?', 'God, quiet my heart the way a parent quiets a child.', 'roots', array['stillness', 'silence', 'rest' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('begin-what-you-have-put-off', 'Begin What You Have Put Off', 'discipline', 15, 'steady', 'medium', 'solo', 'either', 'Choose one small task you have been avoiding, at home or at work, and give it fifteen honest minutes today.', 'Faithfulness is mostly made of small beginnings. Doing ordinary work with care is one way of offering it to God.', 'Colossians 3:23', 'And whatever you do, work heartily, as for the Lord, and not for men,', 'What made this task feel heavy, and what made it lighter once begun?', 'Lord, help me begin, and stay with me in the middle.', 'leaves', array['diligence', 'work', 'faithfulness' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('walk-without-headphones', 'Walk Without Headphones', 'discipline', 15, 'steady', 'medium', 'solo', 'outdoor', 'Take a fifteen-minute walk outside without headphones, noticing what is alive and given around you.', 'Attention is a discipline, and creation is always speaking. A quiet walk is one way to hear it.', 'Psalm 19:1', 'The heavens declare the glory of God. The expanse shows his handiwork.', 'What did you notice that you usually walk past?', 'God, open my eyes to what you have made.', 'sunlight', array['creation', 'attention', 'walking' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian', 'exploring_friendly' ]::text[], '{}'::text[], false, true, 'approved'),
  ('pray-the-examen-before-sleep', 'Pray the Examen Before Sleep', 'prayer', 30, 'steady', 'low', 'solo', 'indoor', 'Before sleep, review the day with God: receive what was given, name where love grew thin, and entrust tomorrow without trying to solve it tonight.', 'The examen trains honest attention without turning prayer into self-accusation. Grace gets the first and final word.', 'Psalm 139:23-24', 'Search me, God, and know my heart. Try me, and know my thoughts. See if there is any wicked way in me, and lead me in the everlasting way.', 'Where did you notice consolation, resistance, or an invitation for tomorrow?', 'Searching God, show me this day in the light of your mercy.', 'roots', array['examen', 'discernment', 'evening' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('intercede-for-your-community-map', 'Intercede With a Community Map', 'prayer', 60, 'devoted', 'medium', 'solo', 'either', 'Sketch the places that hold your community—schools, shelters, clinics, congregations, local government—and spend unhurried time praying for the people within each one.', 'Intercession becomes less abstract when we remember the actual institutions and neighbors whose burdens shape shared life.', '1 Timothy 2:1-2', 'I exhort therefore, first of all, that petitions, prayers, intercessions, and givings of thanks be made for all men: for kings and all who are in high places, that we may lead a tranquil and quiet life in all godliness and reverence.', 'Which place drew your attention, and what faithful action might accompany your prayer?', 'God of every street and household, give our community wisdom, protection, and peace.', 'branches', array['intercession', 'community', 'civic life' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('bring-a-lament-to-god', 'Bring a Lament to God', 'prayer', 30, 'devoted', 'low', 'solo', 'either', 'Write a four-part lament: address God, name what is wrong without polishing it, ask clearly for help, and close with whatever trust you can honestly offer.', 'Biblical lament refuses both denial and despair. It makes room for protest, petition, and relationship with God in the same prayer.', 'Psalm 13:1-2', 'How long, Yahweh? Will you forget me forever? How long will you hide your face from me? How long shall I take counsel in my soul, having sorrow in my heart every day? How long shall my enemy triumph over me?', 'What changed when you named the wound directly instead of explaining it away?', 'How long, O Lord? Meet me in what I cannot repair alone.', 'roots', array['lament', 'honesty', 'suffering' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['grief_sensitive' ]::text[], false, true, 'approved'),
  ('pray-scripture-over-one-person', 'Pray Scripture Over One Person', 'prayer', 30, 'steady', 'low', 'solo', 'either', 'Choose one person and slowly turn each phrase of Colossians 1:9-10 into a specific prayer for their wisdom, endurance, relationships, and work.', 'Praying Scripture widens intercession beyond our immediate solutions and lets the shape of the text tutor our desires.', 'Colossians 1:9-10', 'For this cause, we also, since the day we heard this, don’t cease praying and making requests for you, that you may be filled with the knowledge of his will in all spiritual wisdom and understanding, that you may walk worthily of the Lord, to please him in all respects, bearing fruit in every good work and increasing in the knowledge of God,', 'Which petition felt most needed, and which challenged your assumptions about what they need?', 'God, fill them with wisdom that bears patient and generous fruit.', 'roots', array['intercession', 'scripture prayer', 'wisdom' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('walk-and-pray-your-neighborhood', 'Walk and Pray Your Neighborhood', 'prayer', 60, 'steady', 'medium', 'solo', 'outdoor', 'Walk a familiar route slowly. Pray without guessing private stories: bless the homes, workers, public spaces, and people you actually see, and notice one shared need.', 'A prayer walk can grow responsible love when it attends to real neighbors without treating their lives as scenery or projects.', 'Jeremiah 29:7', 'Seek the peace of the city where I have caused you to be carried away captive, and pray to Yahweh for it; for in its peace you will have peace.”', 'What did you learn by paying attention, and where could prayer become respectful participation?', 'God of this place, teach me to seek my neighbors’ good with humility.', 'branches', array['prayer walk', 'neighborhood', 'attention' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('trace-mercy-through-a-gospel', 'Trace Mercy Through a Gospel', 'scripture', 60, 'devoted', 'medium', 'solo', 'indoor', 'Read one full chapter of Luke and mark every moment when Jesus notices, restores, confronts, or includes someone. Summarize the pattern in your own words.', 'Following a theme through a whole chapter keeps one familiar line from carrying more weight than its narrative context.', 'Luke 7:22-23', 'Jesus answered them, “Go and tell John the things which you have seen and heard: that the blind receive their sight, the lame walk, the lepers are cleansed, the deaf hear, the dead are raised up, and the poor have good news preached to them. Blessed is he who finds no occasion for stumbling in me.”', 'What kind of mercy did you overlook before reading the whole scene?', 'Jesus, let the shape of your mercy correct and enlarge mine.', 'leaves', array['gospel', 'context', 'mercy' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('practice-lectio-divina', 'Practice Lectio Divina', 'scripture', 30, 'steady', 'low', 'solo', 'indoor', 'Read John 15:1-5 four times: listen for a word, notice your response, answer God honestly, then rest in silence without forcing an insight.', 'This ancient rhythm slows interpretation enough for Scripture to become prayer while still honoring the words actually on the page.', 'John 15:4-5', 'Remain in me, and I in you. As the branch can’t bear fruit by itself unless it remains in the vine, so neither can you, unless you remain in me. I am the vine. You are the branches. He who remains in me and I in him bears much fruit, for apart from me you can do nothing.', 'Which word stayed, and how did your response change across the readings?', 'Living Christ, keep me near enough to receive and bear good fruit.', 'leaves', array['lectio divina', 'meditation', 'abiding' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('compare-two-resurrection-accounts', 'Compare Two Resurrection Accounts', 'scripture', 60, 'devoted', 'medium', 'either', 'indoor', 'Read Matthew 28 and John 20 side by side. List what each writer emphasizes, what questions remain, and what both accounts proclaim before consulting a study note.', 'Comparison makes room for each Gospel’s witness instead of flattening distinct voices into a single imagined scene.', 'John 20:30-31', 'Therefore Jesus did many other signs in the presence of his disciples, which are not written in this book; but these are written, that you may believe that Jesus is the Christ, the Son of God, and that believing you may have life in his name.', 'What did one account help you see in the other?', 'Risen Jesus, meet me through the faithful witness of these texts.', 'leaves', array['resurrection', 'study', 'gospels' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('memorize-a-passage-in-context', 'Memorize a Passage in Context', 'scripture', 240, 'devoted', 'medium', 'solo', 'either', 'Read Philippians 2:1-11 in full, then memorize verses 3-5 across several short sessions. Return to the whole passage each time so the lines keep their context.', 'Memory can make Scripture available under pressure; context keeps remembered words from becoming slogans detached from Christ’s way.', 'Philippians 2:3-5', 'doing nothing through rivalry or through conceit, but in humility, each counting others better than himself; each of you not just looking to his own things, but each of you also to the things of others. Have this in your mind, which was also in Christ Jesus,', 'Where does this passage confront ambition, fear, or the need to be noticed?', 'Christ Jesus, form your humility in my reflexes and relationships.', 'leaves', array['memory', 'context', 'humility' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('read-a-minor-prophet-whole', 'Read a Minor Prophet Whole', 'scripture', 60, 'devoted', 'medium', 'solo', 'indoor', 'Read the book of Habakkuk in one sitting. Track the movement from complaint to response to trust, noting where the prophet’s questions remain unresolved.', 'A short biblical book read whole reveals an argument and emotional movement that isolated quotations cannot show.', 'Habakkuk 3:17-18', 'For though the fig tree doesn’t flourish, nor fruit be in the vines; the labor of the olive fails, the fields yield no food; the flocks are cut off from the fold, and there is no herd in the stalls: yet I will rejoice in Yahweh. I will be joyful in the God of my salvation!', 'How does Habakkuk’s final trust differ from pretending circumstances are fine?', 'Faithful God, hold my questions and teach me durable hope.', 'roots', array['prophets', 'whole book', 'lament' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('serve-a-local-need-with-consent', 'Serve a Local Need With Consent', 'service', 240, 'devoted', 'high', 'social', 'either', 'Give a half day to an established local organization. Ask what work is actually useful, follow the leaders closest to the need, and complete the unglamorous task you are given.', 'Service becomes solidarity when it follows community wisdom rather than centering the helper’s assumptions or visibility.', 'Philippians 2:3-4', 'doing nothing through rivalry or through conceit, but in humility, each counting others better than himself; each of you not just looking to his own things, but each of you also to the things of others.', 'What did receiving direction teach you about dignity, power, and useful help?', 'Servant Christ, make me teachable, steady, and willing to do hidden work.', 'branches', array['volunteering', 'solidarity', 'local' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('make-a-practical-help-plan', 'Make a Practical Help Plan', 'service', 60, 'steady', 'medium', 'social', 'indoor', 'Ask someone carrying a real burden what kind of help would reduce it. Agree on one specific task, time, boundary, and follow-up instead of offering a vague promise.', 'Concrete, consent-based help is easier to receive and less likely to create another decision for someone already overloaded.', '1 John 3:17-18', 'But whoever has the world’s goods and sees his brother in need, then closes his heart of compassion against him, how does God’s love remain in him? My little children, let’s not love in word only, or with the tongue only, but in deed and truth.', 'Did your offer match the other person’s stated need, or your preferred way of helping?', 'God of practical love, make my care reliable and respectful.', 'branches', array['care', 'reliability', 'consent' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('offer-caregiver-respite', 'Offer Caregiver Respite', 'service', 240, 'devoted', 'high', 'social', 'either', 'If it is welcome and within your competence, arrange a defined block of practical support for a caregiver—food, errands, sitting nearby, or another task they choose.', 'Caregivers often carry invisible, sustained labor. Reliable respite honors limits and helps a community bear burdens together.', 'Galatians 6:2', 'Bear one another’s burdens, and so fulfill the law of Christ.', 'What structures would make this care sustainable rather than a one-time gesture?', 'Burden-bearing God, strengthen caregivers and teach us to share the load.', 'branches', array['caregiving', 'respite', 'community' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['relationship_sensitive' ]::text[], false, true, 'approved'),
  ('repair-a-shared-space', 'Repair a Shared Space', 'service', 60, 'steady', 'high', 'either', 'either', 'Choose one neglected task in a shared space—cleaning, restocking, mending, organizing, or reporting a repair—and complete it without needing credit.', 'Common life depends on maintenance that is easy to overlook. Hidden care can make a place safer and more welcoming for everyone.', 'Colossians 3:23-24', 'And whatever you do, work heartily, as for the Lord, and not for men, knowing that from the Lord you will receive the reward of the inheritance; for you serve the Lord Christ.', 'Whose often-unseen labor did this task help you notice?', 'God, receive this ordinary work and bless those who share this place.', 'branches', array['shared space', 'hidden work', 'stewardship' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('commit-to-a-month-of-service', 'Commit to a Month of Service', 'service', 480, 'devoted', 'high', 'social', 'either', 'Research one trusted local effort, contact its coordinator, and make a realistic four-week commitment with dates you can honor. Use today to complete the first shift or orientation.', 'Depth usually grows through accountable presence, not a burst of enthusiasm. A bounded commitment makes reliability possible.', 'Hebrews 6:10', 'For God is not unrighteous, so as to forget your work and the labor of love which you showed toward his name, in that you served the saints, and still do serve them.', 'What limit will help you keep this promise without resentment or burnout?', 'Steadfast God, make my yes honest and my service enduring.', 'branches', array['commitment', 'volunteering', 'faithfulness' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('prepare-for-a-repairing-conversation', 'Prepare for a Repairing Conversation', 'kindness', 60, 'devoted', 'medium', 'social', 'indoor', 'Prepare for one safe conversation where harm or misunderstanding needs repair. Write what you can own, what you need to ask, and what boundary keeps the exchange truthful.', 'Kindness is not avoidance. Careful preparation can hold honesty, responsibility, and another person’s dignity together.', 'Ephesians 4:15', 'but speaking truth in love, we may grow up in all things into him who is the head, Christ,', 'What can you take responsibility for without taking responsibility for everything?', 'God of truth and grace, govern my words and guard every person’s dignity.', 'flowers', array['repair', 'truth', 'communication' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['relationship_sensitive' ]::text[], false, true, 'approved'),
  ('advocate-without-taking-over', 'Advocate Without Taking Over', 'kindness', 60, 'devoted', 'high', 'social', 'either', 'With permission, use one piece of access or influence to support someone whose concern is being overlooked. Ask how they want support and keep their voice at the center.', 'Advocacy can practice neighbor-love when it shares power instead of turning another person’s struggle into our own performance.', 'Proverbs 31:8-9', 'Open your mouth for the mute, in the cause of all who are left desolate. Open your mouth, judge righteously, and serve justice to the poor and needy.”', 'Did your action amplify the person’s agency, and what accountability is needed next?', 'God of justice, teach me to use influence with courage and humility.', 'branches', array['advocacy', 'justice', 'agency' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('welcome-someone-new-with-care', 'Welcome Someone New With Care', 'kindness', 30, 'steady', 'medium', 'social', 'indoor', 'At a gathering, introduce yourself to someone who seems new, explain one useful detail, and offer connection without demanding conversation or personal disclosure.', 'Thoughtful welcome lowers the invisible cost of entering an unfamiliar community while respecting a newcomer’s pace.', 'Romans 15:7', 'Therefore accept one another, even as Christ also accepted you, to the glory of God.', 'What made your welcome hospitable rather than intrusive?', 'Welcoming Christ, make room through me without making anyone perform belonging.', 'flowers', array['welcome', 'hospitality', 'belonging' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('honor-a-worker-by-name', 'Honor a Worker by Name', 'kindness', 30, 'steady', 'medium', 'social', 'either', 'Notice someone whose work is easy to treat as invisible. Learn and use their name if appropriate, thank them specifically, and make their work easier rather than interrupting it.', 'Attention can resist the habit of reducing people to services. Specific gratitude recognizes dignity without requiring intimacy.', 'Romans 12:10', 'In love of the brothers be tenderly affectionate to one another; in honor preferring one another;', 'What systems or habits had made this person’s labor easy for you to overlook?', 'God, train my attention toward the dignity of every neighbor.', 'flowers', array['dignity', 'work', 'gratitude' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('practice-a-day-of-attentive-speech', 'Practice a Day of Attentive Speech', 'kindness', 480, 'devoted', 'medium', 'either', 'either', 'For one day, pause before consequential words. Refuse gossip, ask one clarifying question before assuming, and repair quickly if your speech wounds or misrepresents.', 'Speech shapes the emotional climate around us. A full day reveals patterns that a single kind sentence may leave untouched.', 'James 1:19-20', 'So, then, my beloved brothers, let every man be swift to hear, slow to speak, and slow to anger; for the anger of man doesn’t produce the righteousness of God.', 'When was silence wise, and when did love require clear speech?', 'God, set a guard over my mouth and courage in my truthful words.', 'flowers', array['speech', 'listening', 'integrity' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('separate-mercy-from-access', 'Separate Mercy From Access', 'forgiveness', 60, 'devoted', 'low', 'solo', 'indoor', 'Journal two columns: what releasing vengeance to God could mean, and what wise boundaries still require. Do not contact anyone as part of this quest.', 'Forgiveness is not denial, restored trust, or unlimited access. Distinguishing them protects truth and safety while making room for mercy.', 'Romans 12:18-19', 'If it is possible, as much as it is up to you, be at peace with all men. Don’t seek revenge yourselves, beloved, but give place to God’s wrath. For it is written, “Vengeance belongs to me; I will repay, says the Lord.”', 'Which boundary helps you refuse both revenge and renewed harm?', 'Just and merciful God, hold what I cannot safely carry or repair.', 'roots', array['boundaries', 'mercy', 'safety' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['forgiveness_sensitive', 'relationship_sensitive' ]::text[], false, true, 'approved'),
  ('lament-before-you-release', 'Lament Before You Release', 'forgiveness', 30, 'devoted', 'low', 'solo', 'either', 'Name before God what was lost, what should have been different, and what consequence remains. Let lament come before any language of release.', 'Rushing past grief can turn forgiveness into spiritual pressure. Lament honors the truth that mercy does not make harm unreal.', 'Psalm 55:22', 'Cast your burden on Yahweh and he will sustain you. He will never allow the righteous to be moved.', 'What needed acknowledgment before release could become honest?', 'God, receive my grief and keep me from carrying vengeance as my vocation.', 'roots', array['lament', 'release', 'truth' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['forgiveness_sensitive', 'grief_sensitive' ]::text[], false, true, 'approved'),
  ('name-the-loss-beneath-anger', 'Name the Loss Beneath Anger', 'forgiveness', 30, 'steady', 'low', 'solo', 'indoor', 'Without excusing harm, ask what loss your anger is protecting—trust, safety, time, belonging, or hope. Name that loss in prayer or writing.', 'Anger often guards something valuable. Naming the loss can clarify what healing and boundaries actually need.', 'Ephesians 4:26-27', '“Be angry, and don’t sin.” Don’t let the sun go down on your wrath, and don’t give place to the devil.', 'What value or wound became clearer beneath the anger?', 'God, meet the loss beneath my anger and guide my next faithful step.', 'roots', array['anger', 'grief', 'discernment' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['forgiveness_sensitive' ]::text[], false, true, 'approved'),
  ('practice-a-mercy-hour', 'Practice a Mercy Hour', 'forgiveness', 60, 'steady', 'low', 'solo', 'either', 'Set aside an hour to pray for freedom from resentment, write an unsent blessing that does not deny consequences, and choose one boundary or support you need.', 'Forgiveness often unfolds through repeated, bounded practices rather than one decisive feeling.', 'Luke 6:36-37', '“Therefore be merciful, even as your Father is also merciful. Don’t judge, and you won’t be judged. Don’t condemn, and you won’t be condemned. Set free, and you will be set free.', 'What can you release today, and what still needs time, protection, or wise counsel?', 'Merciful God, free me from vengeance without asking me to call harm good.', 'roots', array['mercy', 'resentment', 'boundaries' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['forgiveness_sensitive', 'relationship_sensitive' ]::text[], false, true, 'approved'),
  ('receive-forgiveness-with-repair', 'Receive Forgiveness With Repair', 'forgiveness', 60, 'devoted', 'medium', 'either', 'indoor', 'Name one wrong you have done. Confess it to God, identify repair that does not demand absolution from the harmed person, and take one accountable step if it is safe.', 'Grace frees us to tell the truth and repair what we can; it does not erase consequences or make another person responsible for easing our guilt.', '1 John 1:8-9', 'If we say that we have no sin, we deceive ourselves, and the truth is not in us. If we confess our sins, he is faithful and righteous to forgive us the sins, and to cleanse us from all unrighteousness.', 'What does repentance require beyond feeling sorry?', 'Merciful God, forgive me, make me truthful, and lead me into repair.', 'roots', array['confession', 'repair', 'grace' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['relationship_sensitive' ]::text[], false, true, 'approved'),
  ('build-a-generous-budget-line', 'Build a Generous Budget Line', 'generosity', 60, 'steady', 'medium', 'solo', 'indoor', 'Review one month of spending without shame. Choose a realistic recurring amount or resource to share, name its recipient, and protect your essential needs first.', 'Planned generosity can outlast impulse and make giving both dependable and honest about financial limits.', '2 Corinthians 9:7-8', 'Let each man give according as he has determined in his heart, not grudgingly or under compulsion, for God loves a cheerful giver. And God is able to make all grace abound to you, that you, always having all sufficiency in everything, may abound to every good work.', 'What amount is genuinely sustainable, and what value does it express?', 'Provider God, make me openhanded, prudent, and free from comparison.', 'fruit', array['budget', 'giving', 'sustainability' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['money_sensitive' ]::text[], false, true, 'approved'),
  ('give-a-useful-possession-well', 'Give a Useful Possession Well', 'generosity', 60, 'steady', 'medium', 'either', 'indoor', 'Choose something in good condition that another person or trusted organization has actually requested. Clean it, prepare it, and arrange a respectful handoff.', 'Generosity considers the receiver’s needs and dignity; it is not a way to transfer clutter or create obligation.', 'Luke 3:11', 'He answered them, “He who has two coats, let him give to him who has none. He who has food, let him do likewise.”', 'Did the gift answer a real need, and what made the handoff respectful?', 'Generous God, help me share what is useful with joy and care.', 'fruit', array['possessions', 'sharing', 'dignity' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('share-a-skill-without-charge', 'Share a Skill Without Charge', 'generosity', 240, 'devoted', 'high', 'social', 'either', 'Offer a bounded block of a skill you genuinely have—repair, tutoring, cooking, translation, technology, or administration—to someone or a group that wants it.', 'Time and competence are forms of wealth. A clear scope lets a generous offer remain useful and sustainable.', '1 Peter 4:10', 'As each has received a gift, employ it in serving one another, as good managers of the grace of God in its various forms.', 'How did clear boundaries strengthen rather than diminish the gift?', 'God of varied gifts, let what I know become service rather than status.', 'fruit', array['skills', 'time', 'service' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('contribute-to-mutual-aid', 'Contribute to Mutual Aid', 'generosity', 30, 'steady', 'medium', 'social', 'either', 'Find a transparent, community-led mutual-aid request. Give money, supplies, signal-boosting, or labor within your means, following the stated need exactly.', 'Mutual aid treats people as participants in shared survival rather than passive recipients of someone else’s generosity.', 'Acts 4:34-35', 'For neither was there among them any who lacked, for as many as were owners of lands or houses sold them, and brought the proceeds of the things that were sold, and laid them at the apostles’ feet, and distribution was made to each, according as anyone had need.', 'What did community leadership change about how you offered support?', 'God of enough, teach us to share so needs are met with dignity.', 'fruit', array['mutual aid', 'community', 'dignity' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['money_sensitive' ]::text[], false, true, 'approved'),
  ('host-within-your-means', 'Host Within Your Means', 'generosity', 240, 'devoted', 'high', 'social', 'indoor', 'Invite one or more people into a simple meal or shared time. Ask about access and dietary needs, keep the offering affordable, and let presence matter more than presentation.', 'Hospitality is the generous making of room. Simplicity protects it from becoming performance or financial strain.', '1 Peter 4:9', 'Be hospitable to one another without grumbling.', 'What helped people participate as guests rather than audiences?', 'Welcoming God, make this space spacious in spirit and honest in its limits.', 'fruit', array['hospitality', 'table', 'welcome' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['money_sensitive' ]::text[], false, true, 'approved'),
  ('write-a-sabbath-plan', 'Write a Sabbath Plan', 'discipline', 60, 'devoted', 'medium', 'either', 'indoor', 'Plan one realistic period of Sabbath: what you will stop, what restores delight and worship, who needs notice, and what preparation will keep rest from burdening someone else.', 'Sabbath is more than collapsing after work. Deliberate preparation can make rest, worship, and justice more available.', 'Mark 2:27-28', 'He said to them, “The Sabbath was made for man, not man for the Sabbath. Therefore the Son of Man is lord even of the Sabbath.”', 'Whose labor makes your rest possible, and how will your plan honor them?', 'God of Sabbath, free me from proving my worth and teach me restorative rest.', 'roots', array['sabbath', 'rest', 'planning' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('create-a-digital-rule-of-life', 'Create a Digital Rule of Life', 'discipline', 60, 'steady', 'medium', 'solo', 'indoor', 'Audit one week of digital habits. Write three specific boundaries for attention, sleep, and relationships, then configure one device setting that supports them.', 'Technology is easier to steward through concrete defaults than through repeated acts of willpower and shame.', '1 Corinthians 6:12', '“All things are lawful for me,” but not all things are expedient. “All things are lawful for me,” but I will not be brought under the power of anything.', 'Which tool has quietly begun to master your attention, and what is a proportionate boundary?', 'God, order my attention toward what gives life and love.', 'leaves', array['technology', 'attention', 'rule of life' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['discipline_sensitive' ]::text[], false, true, 'approved'),
  ('finish-a-promised-work', 'Finish a Promised Work', 'discipline', 240, 'devoted', 'high', 'either', 'either', 'Choose one meaningful commitment you have delayed. Clarify the smallest honest definition of done, communicate if expectations changed, and give it a focused half day.', 'Faithfulness includes truthful renegotiation as well as completion. Either is better than silent avoidance.', 'Matthew 5:37', 'But let your ‘Yes’ be ‘Yes’ and your ‘No’ be ‘No.’ Whatever is more than these is of the evil one.', 'Did integrity require finishing, apologizing, renegotiating, or all three?', 'Faithful God, make my commitments clear and my follow-through honest.', 'leaves', array['commitment', 'work', 'integrity' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('practice-hidden-faithfulness', 'Practice Hidden Faithfulness', 'discipline', 30, 'steady', 'medium', 'solo', 'either', 'Do one necessary act of prayer, care, cleaning, preparation, or repair that no one is likely to notice. Resist hinting for recognition afterward.', 'Hidden practice loosens the need for applause and makes room for faithfulness rooted in love rather than image.', 'Matthew 6:3-4', 'But when you do merciful deeds, don’t let your left hand know what your right hand does, so that your merciful deeds may be in secret, then your Father who sees in secret will reward you openly.', 'What did the desire to be noticed reveal, without judging yourself for having it?', 'God who sees in secret, make love enough reward for this work.', 'roots', array['hidden work', 'humility', 'faithfulness' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('keep-a-full-day-of-attention', 'Keep a Full Day of Attention', 'discipline', 480, 'devoted', 'medium', 'either', 'either', 'Choose one day to single-task: silence nonessential alerts, make a short written plan, give people undivided attention, and pause between activities instead of filling every gap.', 'Attention is a finite form of love. A full-day experiment reveals the systems that scatter it and the practices that restore it.', 'Ephesians 5:15-16', 'Therefore watch carefully how you walk, not as unwise, but as wise, redeeming the time, because the days are evil.', 'Where did focused presence change the quality of your work or relationships?', 'God of this present moment, gather my scattered attention into love.', 'leaves', array['attention', 'presence', 'single task' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('write-a-specific-gratitude-letter', 'Write a Specific Gratitude Letter', 'gratitude', 30, 'steady', 'medium', 'social', 'indoor', 'Write to someone whose ordinary faithfulness shaped you. Name a concrete moment, what it cost them, and how its fruit continues—without asking them to reassure or praise you back.', 'Specific thanks honors another person more fully than general praise and helps memory resist taking love for granted.', 'Philippians 1:3-5', 'I thank my God whenever I remember you, always in every request of mine on behalf of you all, making my requests with joy, for your partnership in furtherance of the Good News from the first day until now;', 'What became visible when you traced the lasting fruit of their care?', 'God, thank you for the people through whom your care has reached me.', 'flowers', array['letter', 'memory', 'relationships' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('trace-grace-through-a-hard-year', 'Trace Grace Through a Hard Year', 'gratitude', 60, 'devoted', 'low', 'solo', 'indoor', 'Make a timeline of a difficult season. Name both what hurt and the people, practices, provisions, or moments that helped you endure, without forcing the pain into a lesson.', 'Gratitude can coexist with grief. Honest remembrance notices sustaining grace without calling suffering good.', 'Lamentations 3:21-23', 'This I recall to my mind; therefore I have hope. It is because of Yahweh’s loving kindnesses that we are not consumed, because his compassion doesn’t fail. They are new every morning. Great is your faithfulness.', 'What sustained you that you could not see clearly while surviving?', 'Faithful God, thank you for mercies that did not erase the sorrow but met me in it.', 'roots', array['grief', 'memory', 'grace' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['grief_sensitive' ]::text[], false, true, 'approved'),
  ('thank-three-generations', 'Thank Three Generations', 'gratitude', 60, 'steady', 'medium', 'social', 'either', 'Identify one elder, one peer, and one younger person whose gifts strengthen your community. Thank each specifically in a form that fits your relationship.', 'Gratitude across generations resists the idea that wisdom, energy, or contribution belongs to only one age group.', 'Psalm 145:4', 'One generation will commend your works to another, and will declare your mighty acts.', 'What distinct gift did each generation reveal?', 'God of every generation, teach us to receive and honor one another’s gifts.', 'flowers', array['generations', 'community', 'honor' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('practice-gratitude-without-denial', 'Practice Gratitude Without Denial', 'gratitude', 30, 'steady', 'low', 'solo', 'indoor', 'Complete two honest sentences: “Today is hard because…” and “Today also contains…” Repeat until neither sentence has to cancel the other.', 'Mature gratitude does not suppress sorrow. It expands attention enough to hold pain and gift together.', '2 Corinthians 6:10', 'as sorrowful, yet always rejoicing; as poor, yet making many rich; as having nothing, and yet possessing all things.', 'What truth became possible when you stopped making gratitude compete with grief?', 'God, hold what hurts and help me receive what is still given.', 'roots', array['honesty', 'sorrow', 'gift' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['grief_sensitive' ]::text[], false, true, 'approved'),
  ('lead-table-thanks-with-stories', 'Lead Table Thanks With Stories', 'gratitude', 60, 'steady', 'medium', 'social', 'indoor', 'Invite the people at a meal or gathering to name one gift from the week and the story behind it. Make passing welcome and do not correct anyone’s answer.', 'Shared gratitude deepens when it makes room for particular stories and does not demand a cheerful performance.', 'Psalm 107:1-2', 'Give thanks to Yahweh, for he is good, for his loving kindness endures forever. Let the redeemed by Yahweh say so, whom he has redeemed from the hand of the adversary,', 'What did you learn about another person through the story behind their thanks?', 'Giver of daily bread, receive our varied stories and deepen our care.', 'flowers', array['table', 'stories', 'community' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('practice-centering-prayer', 'Practice Centering Prayer', 'silence', 30, 'steady', 'low', 'solo', 'indoor', 'Choose a simple sacred word as consent to God’s presence. Sit quietly; whenever thoughts carry you away, return gently without evaluating the session.', 'Centering prayer practices consent and return. Its fruit is not a blank mind but a less defensive availability to God.', 'Psalm 62:1-2', 'My soul rests in God alone. My salvation is from him. He alone is my rock, my salvation, and my fortress. I will never be greatly shaken.', 'What did returning gently teach you about distraction and grace?', 'God, I consent to your presence and return without fear.', 'roots', array['centering prayer', 'silence', 'presence' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('take-a-silent-scripture-retreat', 'Take a Silent Scripture Retreat', 'silence', 60, 'devoted', 'low', 'solo', 'either', 'Set aside an uninterrupted hour with a short Gospel passage, a notebook, and silence. Read slowly, walk or sit, and leave the final ten minutes without input.', 'A bounded retreat creates enough space for attention to settle without requiring special travel or spiritual achievement.', 'Mark 6:31', 'He said to them, “You come apart into a deserted place, and rest awhile.” For there were many coming and going, and they had no leisure so much as to eat.', 'What surfaced only after the first layer of noise passed?', 'Jesus, lead me to a quiet place and meet me without hurry.', 'roots', array['retreat', 'scripture', 'quiet' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('keep-a-half-day-digital-silence', 'Keep a Half-Day Digital Silence', 'silence', 240, 'devoted', 'medium', 'solo', 'either', 'Choose four hours without optional screens or audio. Tell anyone who relies on you, keep emergency access available, and use the space for rest, prayer, reading, or unhurried work.', 'Digital silence reveals which inputs restore us and which keep the nervous system from ever becoming quiet.', 'Isaiah 30:15', 'For thus said the Lord Yahweh, the Holy One of Israel, “You will be saved in returning and rest. Your strength will be in quietness and in confidence.” You refused,', 'What urge arrived first when input stopped, and what arrived later?', 'God of quiet strength, meet me beneath the stream of noise.', 'roots', array['digital silence', 'rest', 'attention' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['discipline_sensitive' ]::text[], false, true, 'approved'),
  ('listen-to-the-neighborhood', 'Listen to the Neighborhood', 'silence', 30, 'steady', 'low', 'solo', 'outdoor', 'Sit or walk outdoors without headphones. For thirty minutes, receive sound without naming it good or bad; notice human life, creation, machinery, distance, and silence between sounds.', 'Contemplative listening turns a familiar place from background into a community of lives and limits worthy of attention.', '1 Kings 19:11-12', 'He said, “Go out, and stand on the mountain before Yahweh.” Behold, Yahweh passed by, and a great and strong wind tore the mountains, and broke in pieces the rocks before Yahweh; but Yahweh was not in the wind. After the wind there was an earthquake; but Yahweh was not in the earthquake. After the earthquake a fire passed; but Yahweh was not in the fire. After the fire, there was a still small voice.', 'Which sound changed how you understood the place you inhabit?', 'God, quiet my judgments long enough to hear what is here.', 'sunlight', array['listening', 'neighborhood', 'creation' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('hold-silence-with-unanswered-questions', 'Hold Silence With an Unanswered Question', 'silence', 60, 'devoted', 'low', 'solo', 'indoor', 'Bring one unresolved question into an hour of silence. Write it once, resist manufacturing an answer, and close by naming what you know, what you do not know, and whom you trust.', 'Silence can form patience with mystery and keep discernment from becoming a demand for instant certainty.', 'Habakkuk 2:1', 'I will stand at my watch, and set myself on the ramparts, and will look out to see what he will say to me, and what I will answer concerning my complaint.', 'What changed when you stopped trying to force clarity?', 'God of mystery, keep me faithful while the answer is still unfinished.', 'roots', array['discernment', 'mystery', 'waiting' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('create-a-home-liturgy', 'Create a Home Liturgy', 'worship', 60, 'steady', 'medium', 'either', 'indoor', 'Shape a simple service for your household or yourself: gathering words, one Psalm, confession, Scripture, intercession, gratitude, and a blessing. Keep it brief enough to repeat.', 'A small liturgy gives ordinary space a shared rhythm of truth, prayer, and response without trying to replace gathered church.', 'Colossians 3:16', 'Let the word of Christ dwell in you richly; in all wisdom teaching and admonishing one another with psalms, hymns, and spiritual songs, singing with grace in your heart to the Lord.', 'Which movement helped worship become more than a mood?', 'God, inhabit these ordinary rooms and order our life toward praise.', 'sunlight', array['liturgy', 'home', 'rhythm' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('keep-three-hours-of-prayer', 'Keep Three Hours of Prayer', 'worship', 480, 'devoted', 'medium', 'solo', 'either', 'At morning, midday, and evening, pause for a Psalm, the Lord’s Prayer, and intercession. Set the times now and return even if one pause is imperfect.', 'Fixed-hour prayer lets worship interrupt the day instead of waiting for attention to become convenient.', 'Psalm 55:17', 'Evening, morning, and at noon, I will cry out in distress. He will hear my voice.', 'How did returning at different hours change your awareness of the day?', 'God of morning, noon, and night, gather every hour into your care.', 'sunlight', array['daily office', 'hours', 'rhythm' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('study-and-sing-one-hymn', 'Study and Sing One Hymn', 'worship', 30, 'steady', 'medium', 'solo', 'indoor', 'Choose a hymn or worship song rooted in Scripture. Read the lyrics, identify its claims about God, compare one claim with its biblical source, then sing or speak it attentively.', 'Examining what we sing joins affection with discernment and helps worship form truthful imagination.', 'Ephesians 5:19-20', 'speaking to one another in psalms, hymns, and spiritual songs; singing and making melody in your heart to the Lord; giving thanks always concerning all things in the name of our Lord Jesus Christ, to God, even the Father;', 'Which lyric became richer, harder, or more honest after close attention?', 'God, tune my praise to truth as well as feeling.', 'sunlight', array['hymn', 'theology', 'song' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('make-an-art-offering', 'Make an Art Offering', 'worship', 60, 'steady', 'high', 'solo', 'either', 'Create a poem, sketch, melody, photograph, movement, or handmade object in response to one Psalm. Let it be an offering rather than a product you must post or perfect.', 'Creative worship answers God with the embodied gifts and materials already at hand.', 'Psalm 96:1-2', 'Sing to Yahweh a new song! Sing to Yahweh, all the earth. Sing to Yahweh! Bless his name! Proclaim his salvation from day to day!', 'What did the act of making let you say that ordinary speech did not?', 'Creator God, receive this imperfect work as attentive praise.', 'flowers', array['art', 'creativity', 'psalm' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('take-a-resurrection-praise-walk', 'Take a Resurrection Praise Walk', 'worship', 60, 'devoted', 'high', 'either', 'outdoor', 'Walk outdoors and pray through signs of life, decay, labor, and renewal. Read 1 Corinthians 15:54-58 midway and end by naming work that is not in vain.', 'Resurrection hope does not ignore mortality; it declares that death and faithful labor do not have the final word.', '1 Corinthians 15:57-58', 'But thanks be to God, who gives us the victory through our Lord Jesus Christ. Therefore, my beloved brothers, be steadfast, immovable, always abounding in the Lord’s work, because you know that your labor is not in vain in the Lord.', 'Where did resurrection hope meet the actual world rather than an ideal one?', 'Risen Christ, make me steadfast, hopeful, and alive in your work.', 'sunlight', array['resurrection', 'creation', 'praise' ]::text[], array['easter' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('record-a-family-faith-story', 'Record a Family Faith Story', 'family', 60, 'steady', 'medium', 'social', 'indoor', 'Invite a relative or chosen-family elder to tell one story about faith, doubt, survival, or change. Ask permission before recording or sharing, and listen without correcting their memory.', 'Family stories carry both wisdom and complexity. Consent and curiosity help receive them without turning them into polished legends.', 'Deuteronomy 6:20-21', 'When your son asks you in time to come, saying, “What do the testimonies, the statutes, and the ordinances, which Yahweh our God has commanded you mean?” then you shall tell your son, “We were Pharaoh’s slaves in Egypt. Yahweh brought us out of Egypt with a mighty hand;', 'What did the story reveal about both faith and the world that shaped it?', 'God of our complicated histories, help us receive truth with gratitude and care.', 'branches', array['story', 'generations', 'listening' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['relationship_sensitive' ]::text[], false, true, 'approved'),
  ('offer-a-household-blessing', 'Offer a Household Blessing', 'family', 30, 'steady', 'low', 'social', 'indoor', 'Write a brief blessing for the people who share your home or form your chosen family. Speak or send it only in a way that respects each person’s beliefs and comfort.', 'A blessing names belovedness and hope without controlling another person’s spiritual response.', 'Numbers 6:24-26', '‘Yahweh bless you, and keep you. Yahweh make his face to shine on you, and be gracious to you. Yahweh lift up his face toward you, and give you peace.’', 'What good did you most want to name over this household?', 'God, keep this household in peace, courage, truth, and generous love.', 'branches', array['blessing', 'household', 'chosen family' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('hold-a-family-boundaries-conversation', 'Hold a Family Boundaries Conversation', 'family', 60, 'devoted', 'medium', 'social', 'indoor', 'If it is safe, discuss one recurring household strain using a clear request, a listening turn for each person, and a boundary that no one must violate to keep the peace.', 'Healthy family love needs truth and limits. Peace built on coercion or silence is not the wholeness Scripture describes.', 'Romans 12:18', 'If it is possible, as much as it is up to you, be at peace with all men.', 'What belongs to your responsibility, and what does not?', 'God of peace, make us truthful, safe, and willing to honor wise limits.', 'branches', array['boundaries', 'communication', 'peace' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['relationship_sensitive' ]::text[], false, true, 'approved'),
  ('plan-a-household-service-day', 'Plan a Household Service Day', 'family', 240, 'devoted', 'high', 'social', 'either', 'Choose a community-defined need your household can serve together. Give each person a meaningful role, prepare for access needs, and end by reflecting on what you learned—not how impressive you were.', 'Shared service can form a household when it centers neighbors’ stated needs and makes participation possible across ages and abilities.', 'Joshua 24:15', 'If it seems evil to you to serve Yahweh, choose today whom you will serve; whether the gods which your fathers served that were beyond the River, or the gods of the Amorites, in whose land you dwell; but as for me and my house, we will serve Yahweh.”', 'How did each person contribute, and what should your household learn before serving again?', 'Serving God, shape this household into a reliable neighbor.', 'branches', array['household', 'service', 'participation' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('attend-a-community-meeting', 'Attend a Community Meeting', 'community', 240, 'devoted', 'high', 'social', 'indoor', 'Attend a public, school, neighborhood, or congregational meeting about an issue that affects shared life. Listen before speaking, note who is missing, and identify one responsible follow-up.', 'Seeking a community’s welfare requires learning how decisions are made and whose experience is heard.', 'Jeremiah 29:7', 'Seek the peace of the city where I have caused you to be carried away captive, and pray to Yahweh for it; for in its peace you will have peace.”', 'Whose knowledge shaped the meeting, and whose perspective still needs room?', 'God of the common good, make me patient in listening and faithful in participation.', 'branches', array['civic life', 'listening', 'common good' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('map-your-communitys-assets', 'Map Your Community’s Assets', 'community', 60, 'steady', 'medium', 'either', 'either', 'List not only needs but also the people, associations, places, skills, and traditions already strengthening your community. Add one connection that could help two assets cooperate.', 'Asset mapping resists defining communities only by deficits and honors wisdom that already lives close to the work.', '1 Corinthians 12:4-7', 'Now there are various kinds of gifts, but the same Spirit. There are various kinds of service, and the same Lord. There are various kinds of workings, but the same God, who works all things in all. But to each one is given the manifestation of the Spirit for the profit of all.', 'Which strength had you overlooked because it was ordinary or informal?', 'God of many gifts, help us recognize and connect what you have already given.', 'branches', array['assets', 'community', 'collaboration' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('practice-community-conflict-with-boundaries', 'Practice Community Conflict With Boundaries', 'community', 60, 'devoted', 'medium', 'social', 'indoor', 'For one safe, current disagreement, write the shared concern, the point of conflict, the voices with authority, and a next conversation with ground rules. Seek mediation when power or safety requires it.', 'Faithful conflict neither avoids truth nor treats winning as reconciliation. Structure can protect dignity and accountability.', 'James 3:17-18', 'But the wisdom that is from above is first pure, then peaceful, gentle, reasonable, full of mercy and good fruits, without partiality, and without hypocrisy. Now the fruit of righteousness is sown in peace by those who make peace.', 'What would a just process require, even if agreement remains incomplete?', 'God of wisdom, make our peacemaking pure, open to reason, and full of mercy.', 'branches', array['conflict', 'mediation', 'boundaries' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['relationship_sensitive' ]::text[], false, true, 'approved'),
  ('support-a-weary-community-leader', 'Support a Weary Community Leader', 'community', 30, 'steady', 'medium', 'social', 'either', 'Ask a trusted community leader what small task would genuinely reduce their load this week. Accept the answer, including no, and do not use the offer to gain access or influence.', 'Leaders need care that does not create new emotional labor or hidden obligation. Specific, bounded help can sustain shared work.', '1 Thessalonians 5:12-13', 'But we beg you, brothers, to know those who labor among you, and are over you in the Lord, and admonish you, and to respect and honor them in love for their work’s sake. Be at peace among yourselves.', 'How did you keep support from becoming another demand?', 'God, sustain those who carry responsibility and make our help clean-hearted.', 'branches', array['leadership', 'support', 'boundaries' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('draft-a-rule-of-life', 'Draft a Rule of Life', 'reflection', 60, 'devoted', 'medium', 'solo', 'indoor', 'Draft a one-page rule for prayer, body, work, relationships, rest, money, and service. Choose practices small enough for your real season, plus a date to review them.', 'A rule of life is a trellis, not a scorecard. It helps values become repeatable rhythms while leaving room for grace and revision.', 'John 15:4-5', 'Remain in me, and I in you. As the branch can’t bear fruit by itself unless it remains in the vine, so neither can you, unless you remain in me. I am the vine. You are the branches. He who remains in me and I in him bears much fruit, for apart from me you can do nothing.', 'Which rhythm supports life now, and which ideal belongs to a different season?', 'God, give my days a shape that makes room for love.', 'roots', array['rule of life', 'rhythm', 'discernment' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('discern-a-decision-with-counsel', 'Discern a Decision With Counsel', 'reflection', 60, 'devoted', 'medium', 'either', 'indoor', 'For one meaningful decision, list facts, desires, fears, obligations, affected people, and wise counselors. Name what information is still missing before calling a preference God’s answer.', 'Discernment integrates prayer, reason, community, and consequences rather than using spiritual language to escape uncertainty.', 'Proverbs 15:22', 'Where there is no counsel, plans fail; but in a multitude of counselors they are established.', 'Which desire needs honoring, and which assumption needs testing?', 'God of wisdom, free me from haste and make me receptive to truth.', 'roots', array['discernment', 'decision', 'counsel' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('make-a-season-of-life-timeline', 'Make a Season-of-Life Timeline', 'reflection', 60, 'steady', 'low', 'solo', 'indoor', 'Map the last twelve months with changes, losses, joys, responsibilities, and moments of grace. Circle what still asks for grief, gratitude, repair, or rest.', 'Reflection helps scattered events become a season we can name, receive, and respond to honestly.', 'Ecclesiastes 3:1', 'For everything there is a season, and a time for every purpose under heaven:', 'What season are you actually in—not the one you think you should be in?', 'God of every season, teach me the faithful work of this one.', 'roots', array['timeline', 'season', 'self knowledge' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['grief_sensitive' ]::text[], false, true, 'approved'),
  ('turn-confession-into-a-next-step', 'Turn Confession Into a Next Step', 'reflection', 30, 'steady', 'low', 'solo', 'indoor', 'Name one repeated pattern without contempt. Identify its trigger, its cost, a truthful confession, one repair, and one environmental change that supports a different response.', 'Confession opens toward grace and transformation; shame only circles the self. A concrete next step lets truth bear fruit.', 'Psalm 51:10-12', 'Create in me a clean heart, O God. Renew a right spirit within me. Don’t throw me from your presence, and don’t take your Holy Spirit from me. Restore to me the joy of your salvation. Uphold me with a willing spirit.', 'What support or changed condition could make repentance more than intention?', 'Creating God, renew a steadfast spirit in me and lead me into repair.', 'roots', array['confession', 'habit', 'repair' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('practice-long-listening', 'Practice Long Listening', 'patience', 30, 'steady', 'low', 'social', 'indoor', 'Invite someone to speak about something that matters to them. Ask open questions, leave pauses unfilled, and summarize what you heard before offering advice—if advice is wanted.', 'Patient listening gives another person room to remain the author of their own experience.', 'James 1:19', 'So, then, my beloved brothers, let every man be swift to hear, slow to speak, and slow to anger;', 'What did you hear only because you did not rush to solve?', 'Listening God, slow my answers and deepen my attention.', 'branches', array['listening', 'presence', 'relationships' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('wait-with-someone', 'Wait With Someone', 'patience', 60, 'devoted', 'low', 'social', 'either', 'Offer company to someone waiting through an appointment, transition, grief, decision, or uncertain news. Let them choose conversation, practical help, distraction, or quiet.', 'Presence cannot control an outcome, but it can keep uncertainty from becoming isolation.', 'Romans 12:15', 'Rejoice with those who rejoice. Weep with those who weep.', 'What did companionship make possible without fixing the situation?', 'Patient Christ, help me stay present without taking over.', 'branches', array['waiting', 'companionship', 'presence' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], array['grief_sensitive' ]::text[], false, true, 'approved'),
  ('do-unfinished-work-slowly', 'Do Unfinished Work Slowly', 'patience', 60, 'steady', 'medium', 'solo', 'either', 'Choose work that resists quick completion—a repair, skill, garden task, careful reading, or long-form planning—and give it an hour without measuring success by finishing.', 'Patient labor retrains the demand for immediate results and honors growth that cannot be hurried.', 'James 5:7-8', 'Be patient therefore, brothers, until the coming of the Lord. Behold, the farmer waits for the precious fruit of the earth, being patient over it, until it receives the early and late rain. You also be patient. Establish your hearts, for the coming of the Lord is at hand.', 'What became possible when progress mattered more than completion?', 'God of slow growth, steady my hands and enlarge my time horizon.', 'leaves', array['slow work', 'craft', 'perseverance' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved'),
  ('write-a-patient-hope-plan', 'Write a Patient Hope Plan', 'patience', 60, 'devoted', 'medium', 'solo', 'indoor', 'For one hope that may take months, write what is within your control, what is not, what support you need, the next review date, and how you will live meaningfully while you wait.', 'Patient hope is active without pretending to command timing. It pairs faithful action with release of the outcome.', 'Romans 8:24-25', 'For we were saved in hope, but hope that is seen is not hope. For who hopes for that which he sees? But if we hope for that which we don’t see, we wait for it with patience.', 'What can you practice now without treating the future as a verdict on your worth?', 'God of hope, make me faithful in action and free in what I release.', 'roots', array['hope', 'planning', 'waiting' ]::text[], array['ordinary_time' ]::text[], array['broadly_christian' ]::text[], '{}'::text[], false, true, 'approved')
) as value(slug, title, category, duration_minutes, difficulty, energy_level, solo_or_social, indoor_or_outdoor, invitation, why_it_matters, scripture_reference, scripture_text_snapshot, reflection_prompt, prayer_prompt, growth_type, tags, season_tags, tradition_tags, sensitivity_tags, is_premium, is_active, review_status)
where provider.key = 'christianity'
on conflict (slug) do update set
  faith_provider_id = excluded.faith_provider_id,
  title = excluded.title, category = excluded.category,
  duration_minutes = excluded.duration_minutes, difficulty = excluded.difficulty,
  energy_level = excluded.energy_level, solo_or_social = excluded.solo_or_social,
  indoor_or_outdoor = excluded.indoor_or_outdoor, invitation = excluded.invitation,
  why_it_matters = excluded.why_it_matters,
  scripture_reference = excluded.scripture_reference,
  scripture_text_snapshot = excluded.scripture_text_snapshot,
  reflection_prompt = excluded.reflection_prompt, prayer_prompt = excluded.prayer_prompt,
  growth_type = excluded.growth_type, tags = excluded.tags,
  season_tags = excluded.season_tags, tradition_tags = excluded.tradition_tags,
  sensitivity_tags = excluded.sensitivity_tags, is_premium = excluded.is_premium,
  is_active = excluded.is_active, review_status = excluded.review_status,
  updated_at = now();

commit;
